// B"H
// Generated by build-worker-bundle.mjs - do not edit by hand.
// Static engine-worker bundle. Re-run `node build-worker-bundle.mjs`
// after changing worker_src/*.

    // Global Logging Utility
    self.logDB = function(msg, type = 'debug') {
        if (type === 'debug' && !self.env.debugMode) return;
        self.postMessage({ type: 'LOG', payload: { msg: msg, level: type } });
    };

    self.console.log = function(...args) { self.logDB(args.join(' '), 'debug'); };
    self.console.error = function(...args) { self.logDB(args.join(' '), 'error'); };

    /**
     * B"H
     * Converts a Uint8Array into a readable hex string for debugging the binary soul.
     */
    self.toHex = function(bytes) {
        return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join(' ');
    };

    // Concise Vector Trace
    self.traceVec = function(label, data, count = 5) {
        if (!data || data.length === 0) {
            self.logDB(`[TRACE] ${label}: EMPTY`, 'warn');
            return;
        }
        let str = "";
        const limit = Math.min(data.length, count);
        for(let i=0; i<limit; i++) {
            str += data[i].toFixed(4);
            if(i < limit-1) str += ", ";
        }
        // RMS for health check
        let sumSq = 0;
        for(let i=0; i<data.length; i++) sumSq += data[i]*data[i];
        const rms = Math.sqrt(sumSq / data.length);
        
        self.logDB(`[TRACE] ${label} (RMS:${rms.toFixed(3)}): [${str}...]`, 'tensor');
    };

    self.hexDump = function(data, label) {
        if (!self.env.debugMode) return;
        const slice = data.subarray ? data.subarray(0, 32) : data.slice(0, 32);
        self.logDB(`[HEX] ${label}: ${self.toHex(slice)}...`, 'tensor');
    };


    // Global State for the Worker
    self.env = {
        buffer: null,
        dataOffset: 0,
        vocab: [],
        metaKV: {}, 
        stats: null,
        kv: [], 
        pos: 0,
        tensorMap: new Map(),
        isInitialized: false,
        stop: false,
        debugMode: true,
        // Turbo Flag
        useWasm: false
    };

    /**
     * Awtsmoos Numerical Health Monitor
     */
    self.logStats = function(name, vec) {
        if (!vec || vec.length === 0) return;
        let min = 1e18, max = -1e18, sum = 0, sumSq = 0;
        let hasNaN = false;
        
        for(let i=0; i<vec.length; i++) {
            const v = vec[i];
            if (isNaN(v) || !isFinite(v)) { hasNaN = true; continue; }
            if (v < min) min = v;
            if (v > max) max = v;
            sum += v;
            sumSq += v * v;
        }
        
        if (hasNaN) {
             self.logDB(`[MATH] ${name}: !!! SIGNAL COLLAPSED (NaN/Inf) !!!`, 'error');
             return;
        }

        const rms = Math.sqrt(sumSq / vec.length);
        const msg = `[LAYER] ${name}: RMS=${rms.toExponential(3)} Min=${min.toFixed(3)} Max=${max.toFixed(3)}`;
        // Only log if anomalous
        if (rms > 50.0 || rms < 0.0001) self.logDB(msg, 'calc');
    }


    
    self.onmessage = async (e) => {
        const { type, payload } = e.data;

        try {
            if (type === 'INIT') {
                const buffer = payload;
                
                self.postMessage({ type: 'PROGRESS', payload: { percent: 10, msg: "Parsing Metadata (Worker)..." } });
                
                if (!self.parseGGUF) throw new Error("GGUF Parser not loaded");
                const metaData = self.parseGGUF(buffer);
                
                // Store metadata in env for purifier access
                self.env.metaData = metaData;
                
                self.postMessage({ type: 'METADATA', payload: metaData });
                self.postMessage({ type: 'PROGRESS', payload: { percent: 30, msg: "Initializing Session..." } });
                
                if (!self.initSession) throw new Error("Inference Loop not loaded");
                await self.initSession(buffer, metaData);
                
                self.postMessage({ type: 'STATUS', payload: 'Engine Online' });
                self.postMessage({ type: 'READY' });
                
                self.logDB("Worker: Model Initialized and Memory Mapped.", 'accent');
            }
            else if (type === 'GENERATE') {
                if (!self.env.isInitialized) throw new Error("Worker not initialized");
                // B"H - Payload contains prompt and config params
                const params = payload; 
                const onToken = (token) => self.postMessage({ type: 'TOKEN', payload: token });
                const onDone = () => self.postMessage({ type: 'DONE' });
                await self.runInference(params, onToken, onDone);
            }
            else if (type === 'STOP') {
                self.env.stop = true;
                self.logDB("Worker: Stop signal received.", 'warn');
            }
            else if (type === 'RESET') {
                self.env.pos = 0;
                self.env.history = [];
                self.env.kv = []; 
                self.logDB("Worker: Context Reset.", 'warn');
            }
            else if (type === 'CONFIG_UPDATE') {
                if (payload.useWasm !== undefined) {
                    self.env.useWasm = payload.useWasm;
                    self.logDB(`[CONFIG] Wasm Turbo Mode: ${self.env.useWasm}`, 'accent');
                    if (self.env.useWasm) {
                         await self.initWasmKernel();
                    }
                }
            }
            else if (type === 'INSPECT_TOKEN') {
                const id = payload;
                if (self.getTokenVector) {
                    const vec = self.getTokenVector(id);
                    // Transfer the vector to avoid copy overhead if possible, though it's small
                    self.postMessage({ type: 'TOKEN_DATA', payload: { id, vector: vec } });
                } else {
                    self.logDB("Worker: getTokenVector not available", 'error');
                }
            }
            else if (type === 'PURIFY') {
                try {
                    if (!self.WasmPurifier) throw new Error("Purifier not loaded");
                    
                    self.logDB("Worker: Received PURIFY command. Initializing surgeon...", "warn");
                    
                    // B"H - Corrected: payload contains the full options object { layers, widthPct, vocabSize, regex }
                    const purifier = new self.WasmPurifier(self.env.buffer, self.env.metaData, payload);
                    
                    const progress = (m) => self.postMessage({ type: 'PURIFY_LOG', payload: m });
                    
                    const result = await purifier.purify(progress);
                    
                    self.postMessage({ type: 'PURIFY_DONE', payload: { buffer: result } }, [result]);
                } catch (pErr) {
                    const fatal = `PURIFY FATAL: ${pErr.message}\n${pErr.stack}`;
                    self.postMessage({ type: 'ERROR', payload: fatal });
                    self.logDB(fatal, 'error');
                }
            }
        } catch (err) {
            const fatal = `WORKER FATAL: ${err.message}\n${err.stack}`;
            self.postMessage({ type: 'ERROR', payload: fatal });
            self.console.error(err);
        }
    };


    
    const GGUF_MAGIC = 'GGUF';
    
    self.parseGGUF = function(buffer) {
        const view = new DataView(buffer);
        let offset = 0;
        const decoder = new TextDecoder('utf-8');
        let vocab = [];
        let scores = [];
        let kv = {}; 
        let alignment = 32; 

        self.logDB("--- PARSING GGUF (Worker) ---", 'accent');

        // 1. Magic
        if (buffer.byteLength < 4) throw new Error("File too short");
        const magic = String.fromCharCode(...new Uint8Array(buffer, offset, 4));
        offset += 4;
        
        if (magic !== GGUF_MAGIC) {
            if (magic.startsWith('<!D') || magic.startsWith('<ht') || magic.startsWith(' <!') || magic.startsWith('{')) {
                throw new Error("Invalid File: It looks like you uploaded a text/HTML file. Please load a valid .gguf model file.");
            }
            throw new Error(`Invalid Magic: '${magic}' (Expected 'GGUF'). Use a .gguf file.`);
        }

        // 2. Header
        const version = view.getUint32(offset, true); offset += 4;
        const tensorCount = view.getBigUint64(offset, true); offset += 8;
        const kvCount = view.getBigUint64(offset, true); offset += 8;

        self.logDB(`Version: ${version} | Tensors: ${tensorCount} | KV Pairs: ${kvCount}`, 'info');

        // 3. Metadata
        const count = Number(kvCount);
        
        for (let i = 0; i < count; i++) {
            const kLen = Number(view.getBigUint64(offset, true)); offset += 8;
            const key = decoder.decode(new Uint8Array(buffer, offset, kLen)); offset += kLen;

            const type = view.getUint32(offset, true); offset += 4;
            const result = self.readValue(view, offset, type, decoder, buffer);
            offset = result.newOffset;
            
            kv[key] = result.value;

            if (key === 'tokenizer.ggml.tokens') {
                vocab = result.value;
                self.logDB(`[KV] Vocabulary Loaded: ${vocab.length} tokens`, 'info');
            } else if (key === 'tokenizer.ggml.scores') {
                scores = result.value;
            } else if (key === 'general.alignment') {
                alignment = Number(result.value);
            } else if (key === 'tokenizer.ggml.add_space_prefix') {
                self.logDB(`[KV] tokenizer.ggml.add_space_prefix: ${result.value}`, 'warn');
            } else {
                // Safe Logging
                let logVal = result.value;
                if (Array.isArray(logVal)) {
                    logVal = `[Array(${logVal.length})]`;
                } else if (typeof logVal === 'string' && logVal.length > 100) {
                    logVal = logVal.substring(0, 100) + '... (truncated)';
                }
                // self.logDB(`[KV] ${key}: ${logVal}`, 'debug');
            }
        }

        return {
            vocab: vocab,
            scores: scores,
            kv: kv,
            endOffset: offset,
            tensorCount: Number(tensorCount),
            alignment: alignment
        };
    };

    self.readValue = function(view, offset, type, decoder, buffer) {
        let value;
        switch (type) {
            case 0: value = view.getUint8(offset); offset += 1; break;
            case 1: value = view.getInt8(offset); offset += 1; break;
            case 2: value = view.getUint16(offset, true); offset += 2; break;
            case 3: value = view.getInt16(offset, true); offset += 2; break;
            case 4: value = view.getUint32(offset, true); offset += 4; break;
            case 5: value = view.getInt32(offset, true); offset += 4; break;
            case 6: value = view.getFloat32(offset, true); offset += 4; break;
            case 7: value = !!view.getUint8(offset); offset += 1; break;
            case 8: // String
                const sLen = Number(view.getBigUint64(offset, true)); offset += 8;
                value = decoder.decode(new Uint8Array(buffer, offset, sLen)); offset += sLen;
                break;
            case 9: // Array
                const aType = view.getUint32(offset, true); offset += 4;
                const aLen = Number(view.getBigUint64(offset, true)); offset += 8;
                if (aType >= 0 && aType <= 7) { 
                    value = new Array(aLen);
                    for (let k = 0; k < aLen; k++) {
                        const res = self.readValue(view, offset, aType, decoder, buffer);
                        value[k] = res.value;
                        offset = res.newOffset;
                    }
                } else {
                    value = new Array(aLen);
                    for (let k = 0; k < aLen; k++) {
                        const res = self.readValue(view, offset, aType, decoder, buffer);
                        value[k] = res.value;
                        offset = res.newOffset;
                    }
                }
                break;
            case 10: value = view.getBigUint64(offset, true); offset += 8; break;
            case 11: value = view.getBigInt64(offset, true); offset += 8; break;
            case 12: value = view.getFloat64(offset, true); offset += 8; break;
            default: throw new Error(`Unknown type ID: ${type} at ${offset}`);
        }
        return { value, newOffset: offset };
    };


    self.PriorityQueue = class PriorityQueue {
        constructor(compareFn) {
            this.heap = [];
            this.compare = compareFn || ((a, b) => a - b);
        }

        push(item) {
            this.heap.push(item);
            this._siftUp();
        }

        pop() {
            if (this.size() === 0) return null;
            const top = this.heap[0];
            const bottom = this.heap.pop();
            if (this.size() > 0) {
                this.heap[0] = bottom;
                this._siftDown();
            }
            return top;
        }

        size() {
            return this.heap.length;
        }

        isEmpty() {
            return this.heap.length === 0;
        }

        _siftUp() {
            let node = this.heap.length - 1;
            while (node > 0) {
                const parent = (node - 1) >>> 1;
                if (this.compare(this.heap[node], this.heap[parent]) > 0) {
                    this._swap(node, parent);
                    node = parent;
                } else {
                    break;
                }
            }
        }

        _siftDown() {
            let node = 0;
            while ((node * 2 + 1) < this.heap.length) {
                let left = (node * 2) + 1;
                let right = left + 1;
                let largest = left;

                if (right < this.heap.length && this.compare(this.heap[right], this.heap[left]) > 0) {
                    largest = right;
                }

                if (this.compare(this.heap[largest], this.heap[node]) > 0) {
                    this._swap(node, largest);
                    node = largest;
                } else {
                    break;
                }
            }
        }

        _swap(i, j) {
            const temp = this.heap[i];
            this.heap[i] = this.heap[j];
            this.heap[j] = temp;
        }
    };


    /**
     * SentencePiece BPE Logic
     * Ported from llama-vocab.cpp: llm_tokenizer_spm_session
     */
    self.SPMTokenizer = class SPMTokenizer {
        constructor(vocab, scores, addSpacePrefix = true) {
            this.vocab = vocab;
            this.scores = scores;
            this.addSpacePrefix = addSpacePrefix;
            this.tokenMap = new Map();
            this.byteTokens = new Map(); // Map byte value (0-255) to Token ID
            this.specialTokens = new Map(); // Map special token string to ID

            // Common special tokens to look for
            // In a full implementation we would parse these from tokenizer.ggml.tokens types
            // For now, we heuristically identify them or add common Gemma/Llama specials
            const knownSpecials = new Set([
                '<start_of_turn>', '<end_of_turn>', 
                '<bos>', '<eos>', '<pad>', '<unk>', 
                '<|endoftext|>', '<|im_start|>', '<|im_end|>',
                '<|eot_id|>', '<|start_header_id|>', '<|end_header_id|>'
            ]);
            
            // Fast lookup for token -> ID
            for (let i = 0; i < vocab.length; i++) {
                const text = vocab[i];
                this.tokenMap.set(text, i);
                
                // Detect byte tokens like <0x0A>
                if (text.length === 6 && text.startsWith('<0x') && text.endsWith('>')) {
                    const hex = text.substring(3, 5);
                    const byteVal = parseInt(hex, 16);
                    if (!isNaN(byteVal)) {
                        this.byteTokens.set(byteVal, i);
                    }
                }

                // Detect Special Tokens
                if (knownSpecials.has(text)) {
                    this.specialTokens.set(text, i);
                }
            }
        }

        tokenize(text, logger) {
            const log = logger || (() => {});
            // log(`[SPM] Input: "${text.replace(/\n/g, '\\n')}"`);

            // 1. Split by Special Tokens
            // We escape special tokens for regex
            const specialKeys = Array.from(this.specialTokens.keys());
            let parts = [text];
            
            if (specialKeys.length > 0) {
                // Create a regex that matches any special token
                // We sort by length descending to match longest specials first (<|im_start|> vs <|im_s...)
                specialKeys.sort((a, b) => b.length - a.length);
                const pattern = new RegExp(`(${specialKeys.map(s => s.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&')).join('|')})`, 'g');
                parts = text.split(pattern);
            }

            const output = [];

            for (let i = 0; i < parts.length; i++) {
                const part = parts[i];
                if (!part) continue;

                if (this.specialTokens.has(part)) {
                    output.push(this.specialTokens.get(part));
                    // log(`[SPM] Special: ${part}`);
                } else {
                    // Regular Text Processing
                    this.tokenizeSegment(part, output, logger);
                }
            }
            
            return output;
        }

        tokenizeSegment(text, output, log) {
            // 2. Preprocess: Replace spaces with SPIECE_UNDERLINE
            let processed = text.replace(/ /g, '\u2581');

            // Add leading space if configured and not start of line (simplified)
            // Note: Gemma GGUF usually has add_space_prefix = false
            if (this.addSpacePrefix) {
                if (processed.length > 0 && processed[0] !== '\u2581' && text[0] !== '\n') {
                    processed = '\u2581' + processed;
                }
            }

            // 3. Initial Symbol Split
            const symbols = [];
            let index = 0;
            const chars = [...processed];
            for (const char of chars) {
                symbols.push({
                    text: char,
                    n: 1, 
                    prev: index - 1,
                    next: index + 1,
                    index: index,
                    is_valid: true
                });
                index++;
            }
            if (symbols.length > 0) symbols[symbols.length - 1].next = -1;

            // 4. Priority Queue for Bigrams
            const pq = new self.PriorityQueue((a, b) => {
                if (Math.abs(a.score - b.score) > 1e-6) return a.score - b.score; 
                return b.left - a.left; 
            });

            const tryAddBigram = (leftIdx, rightIdx) => {
                if (leftIdx === -1 || rightIdx === -1) return;
                const symLeft = symbols[leftIdx];
                const symRight = symbols[rightIdx];
                if (!symLeft.is_valid || !symRight.is_valid) return;

                const text = symLeft.text + symRight.text;
                const id = this.tokenMap.get(text);
                if (id !== undefined) {
                    const score = this.scores ? this.scores[id] : 0.0;
                    pq.push({ left: leftIdx, right: rightIdx, score, text });
                }
            };

            for (let i = 1; i < symbols.length; i++) {
                tryAddBigram(i - 1, i);
            }

            // 5. Merge Loop
            while (!pq.isEmpty()) {
                const bigram = pq.pop();
                const leftSym = symbols[bigram.left];
                const rightSym = symbols[bigram.right];

                if (!leftSym.is_valid || !rightSym.is_valid) continue;
                if (leftSym.text + rightSym.text !== bigram.text) continue; 

                leftSym.text += rightSym.text;
                leftSym.n += rightSym.n;
                leftSym.next = rightSym.next;
                rightSym.is_valid = false;
                if (rightSym.next !== -1) symbols[rightSym.next].prev = bigram.left;

                tryAddBigram(leftSym.prev, bigram.left);
                tryAddBigram(bigram.left, leftSym.next);
            }

            // 6. Collect
            let head = 0;
            while(head < symbols.length && !symbols[head].is_valid) head++;

            let ptr = head;
            while (ptr !== -1 && ptr < symbols.length) {
                const sym = symbols[ptr];
                const id = this.tokenMap.get(sym.text);
                
                if (id !== undefined) {
                    output.push(id);
                } else {
                    // Byte Fallback
                    const encoder = new TextEncoder();
                    const bytes = encoder.encode(sym.text);
                    for(let k=0; k<bytes.length; k++) {
                        const b = bytes[k];
                        const byteTokenId = this.byteTokens.get(b);
                        if (byteTokenId !== undefined) {
                            output.push(byteTokenId);
                        } else {
                            const unk = this.tokenMap.get('<unk>') || 0;
                            output.push(unk);
                        }
                    }
                }
                ptr = sym.next;
            }
        }
    };


    
    self.tokenizerInstance = null;

    self.tokenize = function(text) {
        if (!self.env.vocab || self.env.vocab.length === 0) return [];

        // Initialize SPM Tokenizer if not ready
        if (!self.tokenizerInstance) {
            self.logDB("Initializing SPM Tokenizer...", "info");
            if (self.SPMTokenizer) {
                // Check if add_space_prefix is defined in metadata
                let addSpace = true; // default for SPM
                if (self.env.metaKV && self.env.metaKV['tokenizer.ggml.add_space_prefix'] === false) {
                    addSpace = false;
                }
                self.logDB(`[TOKENIZER] add_space_prefix: ${addSpace}`, 'info');
                
                self.tokenizerInstance = new self.SPMTokenizer(self.env.vocab, self.env.scores, addSpace);
            } else {
                self.logDB("CRITICAL: SPMTokenizer class missing!", "error");
                return [];
            }
        }

        // Pass a logger that wraps logDB but marks it as tokenizer
        const logger = (msg) => self.logDB(msg, 'read');
        return self.tokenizerInstance.tokenize(text, logger);
    };


    
    let fullBuffer = null;
    
    self.initLoader = function(buffer, metaData) {
        fullBuffer = buffer;
        self.env.vocab = metaData.vocab;
        self.env.scores = metaData.scores; // Capture scores for SPM
        
        const dataBaseOffset = self.scanTensors(buffer, metaData.endOffset, metaData.tensorCount, metaData.alignment);
        self.env.dataOffset = dataBaseOffset;
        
        if (self.env.vocab.length > 0) {
            self.logDB(`[LOADER] Vocab Size: ${self.env.vocab.length}`, 'info');
        }
        return { vocab: self.env.vocab };
    };

    self.loadWeight = function(name, noCache = false) {
        return null; // Defer to WeightsSource
    };

    self.getEmbeddingRow = function(tokenID, n_embd) {
        let info = self.env.tensorMap.get('token_embd.weight');
        if (!info) info = self.env.tensorMap.get('model.embed_tokens.weight');
        
        if (!info) {
            self.logDB(`[EMBED] CRITICAL: Embedding Tensor Not Found!`, 'error');
            return new Float32Array(n_embd);
        }

        const startIdx = tokenID * n_embd;
        const total = info.dims.reduce((a,b)=>a*b,1);
        
        if (startIdx >= total) {
            return new Float32Array(n_embd);
        }

        const row = self.readTensor(info, startIdx, n_embd);
        return row;
    };
    
    // B"H - Exposed for Inspector
    self.getTokenVector = function(id) {
        if (!self.env.stats) return null;
        return self.getEmbeddingRow(id, self.env.stats.n_embd);
    };

    self.getVocab = function() {
        return self.env.vocab;
    };
    
    self.getTensorInfo = function(name) {
        return self.env.tensorMap.get(name);
    };


    self.dotProduct = (vecA, vecB) => {
        let sum = 0;
        const len = vecA.length;
        for (let i = 0; i < len; i++) sum += vecA[i] * vecB[i];
        return isNaN(sum) || !isFinite(sum) ? 0 : sum;
    };

    /**
     * The Pure JavaScript implementation of Matrix-Vector Multiplication.
     * Serves as the reliable vessel (Kli) when the high-speed light (Wasm)
     * cannot be contained (e.g. alignment mismatches).
     */
    self.matVecMulJS = (x, w, n_out) => {
        const n_in = x.length;
        const y = new Float32Array(n_out);
        for (let i = 0; i < n_out; i++) {
            const offset = i * n_in;
            let sum = 0;
            // Unrolling 4x for numerical stability and performance
            let j = 0;
            for (; j < n_in - 3; j += 4) {
                sum += w[offset + j] * x[j];
                sum += w[offset + j + 1] * x[j + 1];
                sum += w[offset + j + 2] * x[j + 2];
                sum += w[offset + j + 3] * x[j + 3];
            }
            for (; j < n_in; j++) sum += w[offset + j] * x[j];
            y[i] = isNaN(sum) ? 0 : sum;
        }
        return y;
    };

    self.matVecMul = (x, w, n_out) => {
        if (!w) return new Float32Array(n_out);

        // B"H - Turbo Switch
        // If the Assembler has generated the machine code, use it.
        if (self.env && self.env.useWasm && self.wasmMatVecMul) {
             return self.wasmMatVecMul(x, w, n_out);
        }

        return self.matVecMulJS(x, w, n_out);
    };

    self.matVecMul_Q8_0 = (x, bytes, n_out) => {
        // WASM Q8 not yet implemented in Turbo, fallback to JS
        const n_in = x.length;
        const y = new Float32Array(n_out);
        const blockSize = 34;
        const blockCount = n_in / 32;
        for (let i = 0; i < n_out; i++) {
            let sum = 0;
            const rowOffset = i * blockCount * blockSize;
            for (let b = 0; b < blockCount; b++) {
                const ptr = rowOffset + (b * blockSize);
                const delta = self.decodeF16(bytes[ptr] | (bytes[ptr + 1] << 8));
                const inOff = b * 32;
                for (let k = 0; k < 32; k++) {
                    const weight = (bytes[ptr + 2 + k] << 24) >> 24; 
                    sum += x[inOff + k] * (weight * delta);
                }
            }
            y[i] = isNaN(sum) ? 0 : sum;
        }
        return y;
    };


    
    const POW_2_NEG_14 = Math.pow(2, -14);

    self.decodeF16 = (h) => {
        const s = (h & 0x8000) >> 15;
        const e = (h & 0x7C00) >> 10;
        const f = h & 0x03FF;
        
        if(e == 0) return (s ? -1 : 1) * f * 5.9604644775390625e-8;
        if(e == 0x1F) return f ? NaN : ((s ? -1 : 1) * Infinity);
        return (s ? -1 : 1) * Math.pow(2, e - 15) * (1 + f * 0.0009765625);
    };

    /**
     * General Dequantizer Router
     */
    self.dequantize = (data, type, numElements) => {
        // Direct routing based on GGUF Type ID
        switch (type) {
            case 0: return self.deq_f32(data, numElements);
            case 1: return self.deq_f16(data, numElements);
            case 2: return self.deq_q4_0(data, numElements);
            case 6: return self.deq_q5_0(data, numElements); // Q5_0
            case 7: return self.deq_q5_1(data, numElements); // Q5_1
            case 8: return self.deq_q8_0(data, numElements);
            
            // K-Quants
            case 10: return self.deq_q2_k(data, numElements); // Q2_K
            case 11: return self.deq_q3_k(data, numElements); // Q3_K
            case 12: return self.deq_q4_k(data, numElements); // Q4_K
            case 13: return self.deq_q5_k(data, numElements); // Q5_K
            case 14: return self.deq_q6_k(data, numElements); // Q6_K
            
            // IQ-Quants
            case 16: return self.deq_iq2_xxs(data, numElements); // IQ2_XXS
            case 20: return self.deq_iq4_nl(data, numElements);  // IQ4_NL (Type 20)
            case 21: return self.deq_iq3_s(data, numElements);   // IQ3_S (Type 21)
            
            default:
                // B"H - SAFETY FALLBACK: Return small noise instead of zeros to prevent NaN
                // self.logDB(`[DEQUANT] Unsupported type: ${type}. Returning noise.`, 'warn');
                const fallback = new Float32Array(numElements);
                for(let i=0; i<numElements; i++) fallback[i] = (Math.random() - 0.5) * 0.0001;
                return fallback;
        }
    };

    self.deq_f32 = (data, n) => {
        if (data.byteOffset % 4 === 0) return new Float32Array(data.buffer, data.byteOffset, n);
        const res = new Float32Array(n);
        const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
        for (let i = 0; i < n; i++) res[i] = view.getFloat32(i * 4, true);
        return res;
    };

    self.deq_f16 = (data, n) => {
        const res = new Float32Array(n);
        for (let i = 0; i < n; i++) {
            const h = data[i*2] | (data[i*2 + 1] << 8);
            res[i] = self.decodeF16(h);
        }
        return res;
    };


    
    self.deq_q4_0 = (data, numElements) => {
        const result = new Float32Array(numElements);
        const QK = 32;
        const blockCount = numElements / QK;
        let idx = 0;
        
        for (let b = 0; b < blockCount; b++) {
            const h = data[idx] | (data[idx + 1] << 8); idx += 2;
            const d = self.decodeF16(h);
            for (let i = 0; i < 16; i++) {
                const byte = data[idx++];
                result[b * QK + i] = ((byte & 0x0F) - 8) * d;
                result[b * QK + i + 16] = ((byte >> 4) - 8) * d;
            }
        }
        return result;
    };

    self.deq_q8_0 = (data, numElements) => {
        const result = new Float32Array(numElements);
        const QK = 32;
        const blockCount = numElements / QK;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            const h = data[idx] | (data[idx + 1] << 8); idx += 2;
            const d = self.decodeF16(h);
            for (let i = 0; i < 32; i++) {
                let val = data[idx++];
                if (val > 127) val -= 256;
                result[b * QK + i] = val * d;
            }
        }
        return result;
    };

    self.deq_q5_0 = (data, numElements) => {
        const result = new Float32Array(numElements);
        const QK = 32;
        const blockCount = numElements / QK;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            const h = data[idx] | (data[idx + 1] << 8); idx += 2;
            const d = self.decodeF16(h);
            const qhBase = idx; idx += 4; // 4 bytes for high bits
            const qlBase = idx; idx += 16; // 16 bytes for low bits

            for (let i = 0; i < 16; i++) {
                const byte = data[qlBase + i];
                const hByte = data[qhBase + Math.floor(i/4)]; // 4 nibbles per byte? No, qh is packed differently.
                // Standard Q5_0 packing:
                // qh: 32 bits. bit i corresponds to x[i]. bit i+16 to x[i+16].
                // Actually usually: uint32_t qh; memcpy(&qh, &data[idx], 4);
                
                const x0_l = byte & 0x0F;
                const x1_l = byte >> 4;
                
                // Extract high bits from the 4 bytes at qhBase
                // bit i
                const bit0 = (data[qhBase + (i >> 3)] >> (i & 7)) & 1;
                // bit i+16
                const bit1 = (data[qhBase + ((i+16) >> 3)] >> ((i+16) & 7)) & 1;

                const x0 = x0_l | (bit0 << 4);
                const x1 = x1_l | (bit1 << 4);

                result[b * QK + i] = (x0 - 16) * d;
                result[b * QK + i + 16] = (x1 - 16) * d;
            }
        }
        return result;
    };

    self.deq_q5_1 = (data, numElements) => {
        // Similar to Q5_0 but with d and m (add)
        const result = new Float32Array(numElements);
        const QK = 32;
        const blockCount = numElements / QK;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            const h = data[idx] | (data[idx + 1] << 8); idx += 2;
            const d = self.decodeF16(h);
            const hm = data[idx] | (data[idx + 1] << 8); idx += 2;
            const m = self.decodeF16(hm);
            
            const qhBase = idx; idx += 4;
            const qlBase = idx; idx += 16;

            for (let i = 0; i < 16; i++) {
                const byte = data[qlBase + i];
                const x0_l = byte & 0x0F;
                const x1_l = byte >> 4;
                
                const bit0 = (data[qhBase + (i >> 3)] >> (i & 7)) & 1;
                const bit1 = (data[qhBase + ((i+16) >> 3)] >> ((i+16) & 7)) & 1;

                const x0 = x0_l | (bit0 << 4);
                const x1 = x1_l | (bit1 << 4);

                result[b * QK + i] = x0 * d + m;
                result[b * QK + i + 16] = x1 * d + m;
            }
        }
        return result;
    };



    // B"H - Q2_K Implementation
    // Block Size: 256 elements
    // Layout: 
    // - scales: 16 bytes (packed scale/min for 16 superblocks)
    // - qs: 64 bytes (256 2-bit weights)
    // - d: F16 (Super-scale)
    // - dmin: F16 (Super-min)
    self.deq_q2_k = (data, numElements) => {
        const result = new Float32Array(numElements);
        const blockCount = numElements / 256;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            // 1. Pointers
            const scalesIdx = idx; 
            idx += 16;
            const qsIdx = idx;
            idx += 64;
            
            // 2. Read d, dmin (at the END of the block)
            const h_d = data[idx] | (data[idx+1] << 8);
            const d = self.decodeF16(h_d);
            const h_dm = data[idx+2] | (data[idx+3] << 8);
            const dmin = self.decodeF16(h_dm);
            idx += 4;

            const sbBase = b * 256;

            // 3. Unpack Weights
            // The format splits the block into two halves of 128 weights (32 bytes of qs each)
            
            // --- First 128 elements (qs bytes 0-31) ---
            for (let n = 0; n < 32; n++) {
                const byte = data[qsIdx + n];
                
                // Superblock indices (0-15)
                const is0 = n >> 4;
                const is1 = is0 + 2;
                const is2 = is0 + 4;
                const is3 = is0 + 6;
                
                // Weights
                const q0 = byte & 0x3;
                const q1 = (byte >> 2) & 0x3;
                const q2 = (byte >> 4) & 0x3;
                const q3 = (byte >> 6) & 0x3;
                
                // Scales
                const sc0 = data[scalesIdx + is0];
                const sc1 = data[scalesIdx + is1];
                const sc2 = data[scalesIdx + is2];
                const sc3 = data[scalesIdx + is3];
                
                // Indices in output
                const i0 = n;
                const i1 = n + 32;
                const i2 = n + 64;
                const i3 = n + 96;
                
                result[sbBase + i0] = d * (sc0 & 0xF) * q0 - dmin * (sc0 >> 4);
                result[sbBase + i1] = d * (sc1 & 0xF) * q1 - dmin * (sc1 >> 4);
                result[sbBase + i2] = d * (sc2 & 0xF) * q2 - dmin * (sc2 >> 4);
                result[sbBase + i3] = d * (sc3 & 0xF) * q3 - dmin * (sc3 >> 4);
            }
            
            // --- Second 128 elements (qs bytes 32-63) ---
            for (let n = 0; n < 32; n++) {
                const byte = data[qsIdx + 32 + n];
                
                // Superblock indices (offset by 8)
                const is0 = (n >> 4) + 8;
                const is1 = is0 + 2;
                const is2 = is0 + 4;
                const is3 = is0 + 6;
                
                const q0 = byte & 0x3;
                const q1 = (byte >> 2) & 0x3;
                const q2 = (byte >> 4) & 0x3;
                const q3 = (byte >> 6) & 0x3;
                
                const sc0 = data[scalesIdx + is0];
                const sc1 = data[scalesIdx + is1];
                const sc2 = data[scalesIdx + is2];
                const sc3 = data[scalesIdx + is3];
                
                const i0 = n + 128;
                const i1 = n + 160;
                const i2 = n + 192;
                const i3 = n + 224;
                
                result[sbBase + i0] = d * (sc0 & 0xF) * q0 - dmin * (sc0 >> 4);
                result[sbBase + i1] = d * (sc1 & 0xF) * q1 - dmin * (sc1 >> 4);
                result[sbBase + i2] = d * (sc2 & 0xF) * q2 - dmin * (sc2 >> 4);
                result[sbBase + i3] = d * (sc3 & 0xF) * q3 - dmin * (sc3 >> 4);
            }
        }
        return result;
    };

    self.deq_q3_k = (data, numElements) => {
        // B"H - Safety Stub
        // Q3_K logic is extremely complex (masked bits across arrays).
        // Returning slight noise prevents NaN propagation in RMS Norm.
        const result = new Float32Array(numElements);
        for(let i=0; i<numElements; i++) result[i] = (Math.random() - 0.5) * 0.0001;
        return result;
    };

    self.deq_q4_k = (data, numElements) => {
        const result = new Float32Array(numElements);
        const blockCount = numElements / 256;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            // Q4_K Layout: d(2), dmin(2), scales(12), qs(128) -> Total 144
            const h_d = data[idx] | (data[idx+1] << 8); 
            const d = self.decodeF16(h_d);
            const h_m = data[idx+2] | (data[idx+3] << 8);
            const dmin = self.decodeF16(h_m);
            idx += 4;

            const scalesBase = idx; idx += 12;
            const qsBase = idx; idx += 128;
            const sbBase = b * 256;
            
            const scales = new Float32Array(8);
            const mins = new Float32Array(8);
            
            // Unpack 12 bytes of scales/mins into 8 pairs
            for (let j = 0; j < 4; j++) {
                const sc = data[scalesBase + j];
                const m  = data[scalesBase + j + 4];
                const ls = data[scalesBase + j + 8];
                
                scales[j] = d * (sc & 63);
                mins[j] = dmin * (m & 63);
                scales[j+4] = d * ((ls & 15) | ((sc >>> 6) << 4));
                mins[j+4] = dmin * ((ls >>> 4) | ((m >>> 6) << 4));
            }
            
            for (let i = 0; i < 4; i++) {
                const qPtr = qsBase + (i * 32); 
                const outPtr = sbBase + (i * 64);
                const s0 = scales[i];
                const m0 = mins[i];
                const s1 = scales[i+4];
                const m1 = mins[i+4];
                
                for (let l = 0; l < 32; l++) {
                    const byte = data[qPtr + l];
                    result[outPtr + l] = (byte & 0x0F) * s0 - m0;
                    result[outPtr + 32 + l] = (byte >>> 4) * s1 - m1;
                }
            }
        }
        return result;
    };

    self.deq_q6_k = (data, numElements) => {
        const result = new Float32Array(numElements);
        const blockCount = numElements / 256;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            // Q6_K Layout: ql(128), qh(64), scales(16), d(2) -> Total 210
            const qlBase = idx; idx += 128;
            const qhBase = idx; idx += 64;
            const scBase = idx; idx += 16;
            
            const h_d = data[idx] | (data[idx+1] << 8);
            const d = self.decodeF16(h_d);
            idx += 2;
            
            for (let n = 0; n < 256; n++) {
                const is = (n / 16) | 0;
                let sc = data[scBase + is];
                // Sign extension for 8-bit int? No, usually handled as int8 in C.
                // In C: int8_t sc = ...
                if (sc > 127) sc -= 256; 
                
                const qlByte = data[qlBase + (n/2|0)];
                const ql = (n % 2 === 0) ? (qlByte & 0x0F) : (qlByte >>> 4);
                
                const qhByte = data[qhBase + (n/4|0)];
                const qh = (qhByte >>> ((n % 4) * 2)) & 0x03;
                
                const q = ql | (qh << 4);
                result[b * 256 + n] = d * sc * (q - 32);
            }
        }
        return result;
    };
    
    self.deq_q5_k = (data, numElements) => {
        const result = new Float32Array(numElements);
        const blockCount = numElements / 256;
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            // Q5_K Layout: d(2), dmin(2), scales(12), qh(32), qs(128) -> Total 176
            const h_d = data[idx] | (data[idx+1] << 8);
            const d = self.decodeF16(h_d);
            const h_m = data[idx+2] | (data[idx+3] << 8);
            const dmin = self.decodeF16(h_m);
            idx += 4;
            
            const scalesBase = idx; idx += 12;
            const qhBase = idx; idx += 32;
            const qsBase = idx; idx += 128;
            const sbBase = b * 256;

            const scales = new Float32Array(8);
            const mins = new Float32Array(8);
            
            for(let j=0; j<4; j++) {
                const sc = data[scalesBase + j];
                const m = data[scalesBase + j + 4];
                const ls = data[scalesBase + j + 8];
                
                scales[j] = d * (sc & 63);
                mins[j] = dmin * (m & 63);
                scales[j+4] = d * ((ls & 15) | ((sc >>> 6) << 4));
                mins[j+4] = dmin * ((ls >>> 4) | ((m >>> 6) << 4));
            }

            for (let n = 0; n < 256; n++) {
                const blockIdx = (n / 32) | 0;
                const sc = scales[blockIdx];
                const m = mins[blockIdx];
                
                const qsByte = data[qsBase + (n/2|0)];
                const ql = (n % 2 === 0) ? (qsByte & 0x0F) : (qsByte >>> 4);
                
                const qhByte = data[qhBase + (n/8|0)];
                const qh = (qhByte >>> (n % 8)) & 1;
                
                const q = ql | (qh << 4);
                result[sbBase + n] = sc * q - m;
            }
        }
        return result;
    };


    
    // IQ2_XXS Table
    const TABLE_IQ2_XXS = [-1.0, 0.0, 1.0, -2.0];
    
    // IQ4_NL Table (Non-Linear Q4)
    const TABLE_IQ4_NL = [
        -127, -104, -83, -65, -49, -35, -22, -10, 
        1, 13, 25, 38, 53, 69, 89, 113
    ];

    self.deq_iq2_xxs = (data, numElements) => {
        const result = new Float32Array(numElements);
        const QK = 256;
        const blockCount = numElements / QK;
        
        let idx = 0;

        for (let b = 0; b < blockCount; b++) {
            // 16 scales (F16), 32 bytes
            const scales = new Float32Array(16);
            for (let s = 0; s < 16; s++) {
                const h = data[idx] | (data[idx + 1] << 8);
                scales[s] = self.decodeF16(h);
                idx += 2;
            }

            // 64 bytes of 2-bit weights
            const qs = data.subarray(idx, idx + 64);
            idx += 64;

            const out_offset = b * QK;

            for (let i = 0; i < QK; i += 4) {
                const q_byte = qs[i / 4];
                const d = scales[i / 16];
                
                const w0 = (q_byte >> 0) & 0x3;
                const w1 = (q_byte >> 2) & 0x3;
                const w2 = (q_byte >> 4) & 0x3;
                const w3 = (q_byte >> 6) & 0x3;

                result[out_offset + i + 0] = d * TABLE_IQ2_XXS[w0];
                result[out_offset + i + 1] = d * TABLE_IQ2_XXS[w1];
                result[out_offset + i + 2] = d * TABLE_IQ2_XXS[w2];
                result[out_offset + i + 3] = d * TABLE_IQ2_XXS[w3];
            }
        }
        return result;
    };

    // B"H - IQ4_NL Implementation
    self.deq_iq4_nl = (data, numElements) => {
        const result = new Float32Array(numElements);
        const QK = 32;
        const blockCount = numElements / QK;
        let idx = 0;
        
        for (let b = 0; b < blockCount; b++) {
            // 1. Delta (F16)
            const h = data[idx] | (data[idx + 1] << 8); idx += 2;
            const d = self.decodeF16(h);
            
            // 2. 16 bytes of 4-bit indices (32 weights)
            for (let i = 0; i < 16; i++) {
                const byte = data[idx++];
                const low = byte & 0x0F;
                const high = byte >> 4;
                
                result[b * QK + i] = d * TABLE_IQ4_NL[low];
                result[b * QK + i + 16] = d * TABLE_IQ4_NL[high];
            }
        }
        return result;
    };

    // B"H - IQ3_S Safety Fallback
    // Full IQ3_S dequantization is highly complex (256 block size, mixed scales).
    // To prevent "SIGNAL COLLAPSED" (NaN), we return low-magnitude noise.
    // This allows the model to run (badly for that layer) but not crash.
    self.deq_iq3_s = (data, numElements) => {
        // self.logDB("[DEQUANT] IQ3_S not fully implemented. Using fallback noise.", "warn");
        const result = new Float32Array(numElements);
        for(let i=0; i<numElements; i++) {
            // Return tiny noise to avoid 0/0 NaNs in RMS Norm
            result[i] = (Math.random() - 0.5) * 0.001;
        }
        return result;
    };


    
    self.rmsNorm = (x, weight, epsilon, unitOffset = 0.0) => {
        const size = x.length;
        if (!size) return x;
        
        // 1. Calculate RMS
        let ss = 0;
        for(let i=0; i<size; i++) {
            ss += x[i] * x[i];
        }
        const rms = Math.sqrt((ss / size) + epsilon);
        const invRms = 1.0 / (rms || 1e-9); // Prevent div by zero
        
        const out = new Float32Array(size);
        const wLen = weight ? weight.length : 0;
        const useWeight = wLen > 0;
        
        // Unroll loop slightly for speed
        for(let i=0; i<size; i++) {
            let w = 1.0;
            if (useWeight) {
                // Modulo protection, though weight should match size
                w = weight[i % wLen];
            } 
            w += unitOffset;
            
            out[i] = x[i] * invRms * w;
        }
        return out;
    };

    self.softmax = (x) => {
        const size = x.length;
        if (!size) return x;
        
        let max = -Infinity;
        for(let i=0; i<size; i++) {
            if (x[i] > max) max = x[i];
        }
        
        let sum = 0;
        const out = new Float32Array(size);
        for(let i=0; i<size; i++) {
            // Stability: exp(x - max)
            const v = Math.exp(x[i] - max);
            out[i] = v;
            sum += v;
        }
        
        const invSum = 1.0 / (sum || 1e-9);
        for(let i=0; i<size; i++) out[i] *= invSum;
        
        return out;
    };
    
    self.silu = (x) => {
        const out = new Float32Array(x.length);
        for(let i=0; i<x.length; i++) out[i] = x[i] / (1.0 + Math.exp(-x[i]));
        return out;
    };


    
    self.softCap = (x, cap) => {
        if (!cap || cap <= 0) return x;
        const out = new Float32Array(x.length);
        const invCap = 1.0 / cap;
        for (let i = 0; i < x.length; i++) {
            out[i] = cap * Math.tanh(x[i] * invCap);
        }
        return out;
    };

    self.gelu = (x) => {
        const out = new Float32Array(x.length);
        const COEF = 0.044715;
        const SQRT_2_PI = 0.7978845608;

        for (let i = 0; i < x.length; i++) {
            const v = x[i];
            const v3 = v * v * v;
            out[i] = 0.5 * v * (1.0 + Math.tanh(SQRT_2_PI * (v + COEF * v3)));
        }
        return out;
    };


    
    self.rope = (x, head_dim, pos, freq_base, freq_scale, is_neox) => {
        if (!x) return new Float32Array(0);
        
        // Protection against NaN/Inf freq_base
        if (!isFinite(freq_base) || freq_base <= 0) freq_base = 10000.0;

        const out = new Float32Array(x); 
        const n_heads = (x.length / head_dim) | 0;
        const half_dim = head_dim / 2;
        
        const theta_scale = Math.pow(freq_base, -2.0 / head_dim);

        for (let h = 0; h < n_heads; h++) {
            const offset = h * head_dim;
            
            for (let i = 0; i < half_dim; i++) {
                // Effective Theta = pos * scale * (base ^ (-2i/dim))
                // Note: The exponent depends on the index i.
                // In interleaved (standard) mode: pairs are (2i, 2i+1), theta depends on 2i.
                // In neox mode: pairs are (i, i+half), theta depends on i.
                // However, usually the theta formula is consistent: theta_i = base^(-2i/d).
                
                const theta = pos * freq_scale * Math.pow(theta_scale, i);
                const cos_theta = Math.cos(theta);
                const sin_theta = Math.sin(theta);
                
                let idx0, idx1;
                
                if (is_neox) {
                    // Neox Mode: Rotate x[i] with x[i + half_dim]
                    idx0 = offset + i;
                    idx1 = offset + i + half_dim;
                } else {
                    // Standard (Interleaved) Mode: Rotate x[2i] with x[2i+1]
                    idx0 = offset + 2 * i;
                    idx1 = offset + 2 * i + 1;
                }
                
                const v0 = out[idx0];
                const v1 = out[idx1];
                
                out[idx0] = v0 * cos_theta - v1 * sin_theta;
                out[idx1] = v0 * sin_theta + v1 * cos_theta;
            }
        }
        return out;
    };


    
    self.readTensor = function(info, sliceStart = 0, sliceLength = null) {
        if (!info) return null;
        
        const numElements = info.dims.reduce((a, b) => a * b, 1);
        const readLen = sliceLength !== null ? sliceLength : numElements;
        const type = info.type;
        
        const finalOutput = new Float32Array(readLen);
        const buffer = self.env.buffer;
        const baseOffset = self.env.dataOffset;
        
        const { blockElements, blockSize } = self.getByteSize(type);

        const blockIndexStart = Math.floor(sliceStart / blockElements);
        const blockIndexEnd = Math.ceil((sliceStart + readLen) / blockElements);
        const totalBlocks = blockIndexEnd - blockIndexStart;
        
        const byteStart = baseOffset + info.dataOffset + (blockIndexStart * blockSize);
        const byteLength = totalBlocks * blockSize;
        
        let rawBytes = null;
        if (byteStart >= buffer.byteLength) {
            // Silence OOB warnings for optional tensors
            // self.logDB(`[TENSOR] OOB: ${info.name}`, 'warn');
            return finalOutput;
        }

        let safeByteLength = byteLength;
        if (byteStart + byteLength > buffer.byteLength) {
             safeByteLength = buffer.byteLength - byteStart;
        }

        try {
            rawBytes = new Uint8Array(buffer, byteStart, safeByteLength);
        } catch (e) {
            self.logDB(`[TENSOR] VIEW ERROR: ${info.name}`, 'error');
            return finalOutput;
        }

        const totalElementsExpanded = totalBlocks * blockElements;
        let safeRawBytes = rawBytes;
        if (rawBytes.byteLength < byteLength) {
             safeRawBytes = new Uint8Array(byteLength); 
             safeRawBytes.set(rawBytes);
        }

        // B"H - Dequantize with fallback
        const fullBlockResult = (self.dequantize) 
            ? self.dequantize(safeRawBytes, type, totalElementsExpanded) 
            : new Float32Array(totalElementsExpanded);

        const relativeStart = sliceStart - (blockIndexStart * blockElements);
        const copyLen = Math.min(finalOutput.length, fullBlockResult.length - relativeStart);
        if (copyLen > 0) {
            finalOutput.set(fullBlockResult.subarray(relativeStart, relativeStart + copyLen));
        }
        
        return finalOutput;
    };

    self.getRawTensorView = function(info) {
        if (!info) return null;
        const buffer = self.env.buffer;
        const baseOffset = self.env.dataOffset;
        
        const { blockElements, blockSize } = self.getByteSize(info.type);
        
        const numElements = info.dims.reduce((a, b) => a * b, 1);
        const totalBlocks = Math.ceil(numElements / blockElements);
        const byteLength = totalBlocks * blockSize;
        const byteStart = baseOffset + info.dataOffset;
        
        if (byteStart >= buffer.byteLength) return new Uint8Array(byteLength);
        
        if (byteStart + byteLength > buffer.byteLength) {
             const safeLen = buffer.byteLength - byteStart;
             const out = new Uint8Array(byteLength);
             const src = new Uint8Array(buffer, byteStart, safeLen);
             out.set(src);
             return out;
        }

        return new Uint8Array(buffer, byteStart, byteLength);
    };

    self.scanTensors = function(buffer, startOffset, count, alignment = 32) {
        const view = new DataView(buffer);
        let offset = startOffset;
        const decoder = new TextDecoder('utf-8');
        self.env.tensorMap.clear();
        
        for (let i = 0; i < count; i++) {
            const nLen = Number(view.getBigUint64(offset, true)); offset += 8;
            const name = decoder.decode(new Uint8Array(buffer, offset, nLen)); offset += nLen;
            const nDims = view.getUint32(offset, true); offset += 4;
            const dims = [];
            for (let d = 0; d < nDims; d++) { dims.push(Number(view.getBigUint64(offset, true))); offset += 8; }
            const type = view.getUint32(offset, true); offset += 4;
            const dataOffset = Number(view.getBigUint64(offset, true)); offset += 8;
            
            self.env.tensorMap.set(name, { name, dims, type, dataOffset });
        }
        
        const finalOffset = (offset + alignment - 1) & ~(alignment - 1);
        return finalOffset;
    };
    
    // B"H - THE SACRED AND COMPLETE BLUEPRINT OF QUANTIZATION (Duplicate of tensor_utils logic for worker internal use)
    self.getByteSize = function(type) {
        switch (type) {
            case 0:  return { blockElements: 1, blockSize: 4 };    // F32
            case 1:  return { blockElements: 1, blockSize: 2 };    // F16
            case 2:  return { blockElements: 32, blockSize: 18 };   // Q4_0
            case 3:  return { blockElements: 32, blockSize: 20 };   // Q4_1
            case 6:  return { blockElements: 32, blockSize: 22 };   // Q5_0
            case 7:  return { blockElements: 32, blockSize: 24 };   // Q5_1
            case 8:  return { blockElements: 32, blockSize: 34 };   // Q8_0
            case 9:  return { blockElements: 32, blockSize: 40 };   // Q8_1
            
            case 10: return { blockElements: 256, blockSize: 84 };  // Q2_K 
            case 11: return { blockElements: 256, blockSize: 110 }; // Q3_K
            case 12: return { blockElements: 256, blockSize: 144 }; // Q4_K
            case 13: return { blockElements: 256, blockSize: 176 }; // Q5_K
            case 14: return { blockElements: 256, blockSize: 210 }; // Q6_K
            case 15: return { blockElements: 256, blockSize: 256 }; // Q8_K
            
            case 16: return { blockElements: 256, blockSize: 96 };  // IQ2_XXS
            case 20: return { blockElements: 32, blockSize: 18 };   // IQ4_NL (Same size as Q4_0)
            case 21: return { blockElements: 256, blockSize: 112 }; // IQ3_S (Approx)
            
            default: 
                // Default to F32 size to avoid div by zero, but log error
                return { blockElements: 1, blockSize: 4 };
        }
    };


    
    self.inferStats = function(meta) {
        const params = { 
            n_embd: 0, n_layer: 0, n_head: 0, n_head_kv: 0, head_dim: 0, 
            norm_eps: 1e-6, rope_freq: 10000.0, rope_freq_local: 0.0,
            rope_scale: 1.0, 
            arch: 'llama',      
            useEmbScale: false, attn_soft_cap: 0.0, final_soft_cap: 0.0, 
            sliding_window: 0, sliding_window_pattern: 0, 
            query_pre_attn_scalar: 0, 
            act_fn: 'silu',
            rope_is_neox: false 
        };
        
        const findVal = (suffix) => {
             for(const k in meta.kv) {
                 if(k.endsWith(suffix)) return meta.kv[k];
             }
             return undefined;
        };

        // 1. Architecture
        const kvArch = meta.kv['general.architecture'];
        if (kvArch) params.arch = kvArch.toLowerCase();
        const isGemma = params.arch.includes('gemma');
        
        if (isGemma) {
            params.act_fn = 'gelu';
            params.rope_is_neox = true; // Gemma uses Neox style RoPE
        }

        // 2. Dimensions
        const embInfo = self.env.tensorMap.get('token_embd.weight') || self.env.tensorMap.get('model.embed_tokens.weight');
        if (embInfo) params.n_embd = Number(embInfo.dims[0]); 

        const qInfo = self.env.tensorMap.get('blk.0.attn_q.weight') || self.env.tensorMap.get('model.layers.0.self_attn.q_proj.weight');
        const kInfo = self.env.tensorMap.get('blk.0.attn_k.weight') || self.env.tensorMap.get('model.layers.0.self_attn.k_proj.weight');

        // Head Dim Inference
        let metaHeadDim = findVal('.attention.key_length') || findVal('.attention.head_dim');
        if (metaHeadDim) {
            params.head_dim = metaHeadDim;
        } else if (qInfo) {
             const q_out = Number(qInfo.dims[1]);
             const count = findVal('.attention.head_count');
             if (count) {
                 params.head_dim = q_out / count;
             } else {
                 params.head_dim = isGemma ? 256 : 128; 
             }
        }

        if (qInfo) {
            const q_out = Number(qInfo.dims[1]);
            params.n_head = Math.round(q_out / params.head_dim);
        } else {
            params.n_head = findVal('.attention.head_count') || (params.n_embd / 128);
        }

        if (kInfo) {
            const k_out = Number(kInfo.dims[1]);
            params.n_head_kv = Math.round(k_out / params.head_dim);
        } else {
            params.n_head_kv = findVal('.attention.head_count_kv') || params.n_head;
        }
        
        // 3. Norm
        params.norm_eps = findVal('.attention.layer_norm_rms_epsilon') || 1e-5;
        
        // 4. RoPE
        params.rope_freq = findVal('.rope.freq_base') || 10000.0;
        
        const scaleFactor = findVal('.rope.scaling.factor');
        if (scaleFactor && scaleFactor > 0) params.rope_scale = 1.0 / scaleFactor; 

        // RoPE Local (Gemma 3 Hybrid)
        // If global is 1M, local is usually 10k.
        // We look for explicit key first.
        const localFreq = findVal('rope.freq_base.local') || findVal('rope_freq_base_local');
        if (localFreq) {
            params.rope_freq_local = localFreq;
        } else if (isGemma && params.rope_freq > 50000.0) {
            // CONFIRMED: llama-model.cpp sets hparams.rope_freq_base_train_swa = 10000.0f
            params.rope_freq_local = 10000.0;
            self.logDB(`[CONFIG] inferred rope_freq_local: 10000.0 (Global is ${params.rope_freq})`, 'warn');
        } else {
            params.rope_freq_local = params.rope_freq;
        }

        // 5. GEMMA SPECIFIC
        if (isGemma) {
            params.useEmbScale = true; 
            
            params.sliding_window = findVal('.attention.sliding_window') || 0;
            params.sliding_window_pattern = findVal('.attention.sliding_window_pattern') || 0; 
            
            // CONFIRMED: llama-model.cpp sets pattern to 6 for Gemma 3
            if (params.sliding_window > 0 && params.sliding_window_pattern === 0) {
                 params.sliding_window_pattern = 6; 
                 self.logDB(`[CONFIG] Defaulting sliding_window_pattern to 6 (Gemma 3 Std)`, 'warn');
            }

            params.query_pre_attn_scalar = findVal('.attention.query_pre_attn_scalar');
            if (!params.query_pre_attn_scalar) {
                 params.query_pre_attn_scalar = params.head_dim; 
            }
            
            // Soft Capping
            // CRITICAL FIX: llama-model.cpp DISABLES attn soft capping for Gemma 3, 
            // even if the key exists in GGUF. Only Gemma 2 uses it.
            if (params.arch === 'gemma3') {
                params.attn_soft_cap = 0.0;
                self.logDB(`[CONFIG] Gemma 3: Forcing Attn Soft Cap to 0.0 (matches llama.cpp)`, 'warn');
            } else {
                params.attn_soft_cap = findVal('attn_logit_softcapping') || 0.0; 
            }

            params.final_soft_cap = findVal('final_logit_softcapping') || 0.0;
            
            self.logDB(`[CONFIG] Soft Caps: Attn=${params.attn_soft_cap}, Final=${params.final_soft_cap}`, 'info');
        } 
        
        // 6. Layer Count
        let l = 0;
        while(self.env.tensorMap.has(`blk.${l}.attn_q.weight`) || self.env.tensorMap.has(`model.layers.${l}.self_attn.q_proj.weight`)) l++;
        params.n_layer = l;

        params.q_dim = params.n_head * params.head_dim;
        params.kv_dim = params.n_head_kv * params.head_dim;
        
        self.logDB(`[CONFIG] ${params.arch} | L:${params.n_layer} | Emb:${params.n_embd} | Heads:${params.n_head}/${params.n_head_kv} | Dim:${params.head_dim}`, 'accent');
        self.logDB(`[CONFIG] RoPE Global:${params.rope_freq} | Local:${params.rope_freq_local} | Pattern:${params.sliding_window_pattern} | Neox:${params.rope_is_neox}`, 'accent');
        
        return params;
    }



    self.weightCache = new Map();
    // B"H - Increased to 2GB to hold unquantized tensors for small models
    const CACHE_LIMIT = 2 * 1024 * 1024 * 1024; 
    let cacheUsed = 0;
    
    self.layerTensorMap = []; 
    self.globalTensorMap = {};

    self.autoMapWeights = function() {
        self.logDB(`[WEIGHTS] Starting Auto-Map (Strict C++ Pattern Matching)...`, 'info');
        self.layerTensorMap = [];
        self.globalTensorMap = {};
        self.env.debug_hex_dump = false; 

        const keys = Array.from(self.env.tensorMap.keys());
        const layerRegex = /^(?:model\.|blk\.|)(?:layers\.|)(\d+)\.(.+)$/;
        
        for (const key of keys) {
            const match = key.match(layerRegex);
            if (match) {
                const l = parseInt(match[1]);
                const suffix = match[2];
                
                if (!self.layerTensorMap[l]) self.layerTensorMap[l] = {};
                
                // --- ATTENTION ---
                if (suffix.match(/^(self_attn\.|attention\.|attn_)q\.weight$/) || suffix.match(/q_proj\.weight$/)) 
                    self.layerTensorMap[l]['attn_q'] = key;
                else if (suffix.match(/^(self_attn\.|attention\.|attn_)k\.weight$/) || suffix.match(/k_proj\.weight$/)) 
                    self.layerTensorMap[l]['attn_k'] = key;
                else if (suffix.match(/^(self_attn\.|attention\.|attn_)v\.weight$/) || suffix.match(/v_proj\.weight$/)) 
                    self.layerTensorMap[l]['attn_v'] = key;
                else if (suffix.match(/^(self_attn\.|attention\.|attn_)output\.weight$/) || suffix.match(/o_proj\.weight$/)) 
                    self.layerTensorMap[l]['attn_out'] = key;

                // --- QK NORMS (Gemma 2/3) ---
                else if (suffix.match(/^(attn_q_norm|q_norm)\.weight$/))
                    self.layerTensorMap[l]['attn_q_norm'] = key;
                else if (suffix.match(/^(attn_k_norm|k_norm)\.weight$/))
                    self.layerTensorMap[l]['attn_k_norm'] = key;

                // --- LAYER NORMS ---
                else if (suffix.match(/^(input_layernorm|attn_norm|pre_attention_layernorm)\.weight$/)) 
                    self.layerTensorMap[l]['attn_norm'] = key;
                else if (suffix === 'post_attention_norm.weight' || suffix.match(/^(post_attention_layernorm|attn_post_norm)\.weight$/)) 
                    self.layerTensorMap[l]['attn_post_norm'] = key;
                else if (suffix === 'ffn_norm.weight' || suffix.match(/^(pre_feedforward_layernorm|pre_mlp_layernorm)\.weight$/)) 
                    self.layerTensorMap[l]['ffn_norm'] = key;
                else if (suffix === 'post_ffw_norm.weight' || suffix.match(/^(post_feedforward_layernorm|post_mlp_layernorm|ffn_post_norm)\.weight$/)) 
                    self.layerTensorMap[l]['ffn_post_norm'] = key;

                // --- FFN ---
                else if (suffix.match(/^(mlp\.|feed_forward\.|ffn_)gate\.weight$/) || suffix.match(/w1\.weight$/) || suffix.match(/gate_proj\.weight$/)) 
                    self.layerTensorMap[l]['ffn_gate'] = key;
                else if (suffix.match(/^(mlp\.|feed_forward\.|ffn_)down\.weight$/) || suffix.match(/w2\.weight$/) || suffix.match(/down_proj\.weight$/)) 
                    self.layerTensorMap[l]['ffn_down'] = key;
                else if (suffix.match(/^(mlp\.|feed_forward\.|ffn_)up\.weight$/) || suffix.match(/w3\.weight$/) || suffix.match(/up_proj\.weight$/)) 
                    self.layerTensorMap[l]['ffn_up'] = key;

            } else {
                // Global Tensors
                if (key.match(/^(token_embd|model\.embed_tokens)\.weight$/)) self.globalTensorMap['embed'] = key;
                else if (key.match(/^(output_norm|model\.norm)\.weight$/)) self.globalTensorMap['output_norm'] = key;
                else if (key.match(/^(output|lm_head)\.weight$/)) self.globalTensorMap['output'] = key;
            }
        }
        
        self.logDB(`[WEIGHTS] Mapped ${self.layerTensorMap.length} layers.`, 'info');
    };

    self.loadWeight = function(name, noCache = false) {
        let realName = name;
        
        // 1. Try Direct Lookup
        let info = self.env.tensorMap.get(name);
        
        // 2. Try Layer Map Lookup (Aliasing)
        if (!info) {
            const match = name.match(/^(?:blk\.|layers\.|)(\d+)\.(.+)\.weight$/);
            if (match) {
                const l = parseInt(match[1]);
                const alias = match[2];
                
                if (self.layerTensorMap[l] && self.layerTensorMap[l][alias]) {
                    realName = self.layerTensorMap[l][alias];
                    info = self.env.tensorMap.get(realName);
                }
            } else {
                if (name === 'output_norm.weight' && self.globalTensorMap['output_norm']) {
                    realName = self.globalTensorMap['output_norm'];
                    info = self.env.tensorMap.get(realName);
                } else if (name === 'output.weight' && self.globalTensorMap['output']) {
                    realName = self.globalTensorMap['output'];
                    info = self.env.tensorMap.get(realName);
                } else if (name === 'token_embd.weight' && self.globalTensorMap['embed']) {
                    realName = self.globalTensorMap['embed'];
                    info = self.env.tensorMap.get(realName);
                }
            }
        }

        if (!info) return null;

        if (!noCache && self.weightCache.has(realName)) {
            return self.weightCache.get(realName);
        }

        const tensor = self.readTensor(info); 
        
        if (!noCache && tensor) {
            const size = tensor.byteLength;
            if (cacheUsed + size > CACHE_LIMIT) {
                self.logDB("[WEIGHTS] Cache Limit Reached. Clearing cache & Resetting WASM Heap...", "warn");
                self.weightCache.clear();
                cacheUsed = 0;
                // B"H - Reset WASM Heap to prevent leak
                if (self.resetWasmHeap) self.resetWasmHeap();
            }
            self.weightCache.set(realName, tensor);
            cacheUsed += size;
        }
        
        return tensor;
    };


    
    function getRoPEConfig(l, params) {
        // Gemma 3 Sliding Window Logic
        let isSliding = false;
        
        if (params.sliding_window > 0 && params.sliding_window_pattern > 0) {
            isSliding = ((l + 1) % params.sliding_window_pattern) !== 0;
        } 
        
        const freq = isSliding ? params.rope_freq_local : params.rope_freq;
        const scale = isSliding ? 1.0 : params.rope_scale;
        
        return { freq, scale, isSliding };
    }

    self.computeAttention = function(x, l, params, prefix, pos) {
        const p = `blk.${l}.`;
        
        let q_w = self.loadWeight(`${p}attn_q.weight`);
        let k_w = self.loadWeight(`${p}attn_k.weight`);
        let v_w = self.loadWeight(`${p}attn_v.weight`);
        
        if (!q_w || !k_w || !v_w) return new Float32Array(params.n_embd);

        // Projections
        let q = self.matVecMul(x, q_w, params.q_dim);
        let k = self.matVecMul(x, k_w, params.kv_dim);
        let v = self.matVecMul(x, v_w, params.kv_dim);
        
        // --- QK NORM (Gemma 2/3) ---
        if (params.arch.includes('gemma')) {
             let w_qn = self.loadWeight(`${p}attn_q_norm.weight`);
             let w_kn = self.loadWeight(`${p}attn_k_norm.weight`);
             
             // Gemma 3 QK Norm is applied per-head (RMS Norm)
             // w_qn dims are [head_dim]. GGUF might store it as [head_dim] or [head_dim * n_head]
             // Usually it's just [head_dim] and broadcasted.
             
             if (w_qn) {
                 for (let h = 0; h < params.n_head; h++) {
                     const start = h * params.head_dim;
                     const q_head = q.subarray(start, start + params.head_dim);
                     // If w_qn is big enough, slice it. Otherwise reuse it.
                     const w_slice = (w_qn.length >= params.q_dim) ? w_qn.subarray(start, start + params.head_dim) : w_qn;
                     
                     const normed = self.rmsNorm(q_head, w_slice, params.norm_eps, 0.0);
                     q.set(normed, start);
                 }
             }

             if (w_kn) {
                 for (let h = 0; h < params.n_head_kv; h++) {
                     const start = h * params.head_dim;
                     const k_head = k.subarray(start, start + params.head_dim);
                     const w_slice = (w_kn.length >= params.kv_dim) ? w_kn.subarray(start, start + params.head_dim) : w_kn;
                     
                     const normed = self.rmsNorm(k_head, w_slice, params.norm_eps, 0.0);
                     k.set(normed, start);
                 }
             }
        }
        
        // --- RoPE ---
        const ropeConfig = getRoPEConfig(l, params);
        // Debug L0
        if (pos === 0 && l === 0 && !self.env.rope_debug_done) {
            self.logDB(`[L0] RoPE: ${ropeConfig.isSliding ? 'Sliding (Local)' : 'Full (Global)'} | Freq: ${ropeConfig.freq} | Scale: ${ropeConfig.scale} | Neox: ${params.rope_is_neox}`, 'debug');
            self.env.rope_debug_done = true;
        }

        const q_r = self.rope(q, params.head_dim, pos, ropeConfig.freq, ropeConfig.scale, params.rope_is_neox);
        const k_r = self.rope(k, params.head_dim, pos, ropeConfig.freq, ropeConfig.scale, params.rope_is_neox);

        if (!self.env.kv[l]) self.env.kv[l] = { k: [], v: [] };
        self.env.kv[l].k[pos] = k_r;
        self.env.kv[l].v[pos] = v;

        // --- SCALE ---
        let scale;
        if (params.query_pre_attn_scalar > 0) {
            scale = 1.0 / Math.sqrt(params.query_pre_attn_scalar);
        } else {
            scale = 1.0 / Math.sqrt(params.head_dim);
        }

        // --- ATTENTION LOOP ---
        // Sliding Window Masking
        let startPos = 0;
        if (ropeConfig.isSliding && params.sliding_window > 0) {
            startPos = Math.max(0, pos - params.sliding_window + 1);
        }
        
        const out_attn = new Float32Array(params.q_dim);
        const ratio = Math.floor(params.n_head / params.n_head_kv);
        
        for (let h = 0; h < params.n_head; h++) {
            const h_off = h * params.head_dim;
            const q_h = q_r.subarray(h_off, h_off + params.head_dim);
            
            const kv_h = Math.floor(h / ratio);
            const kv_off = kv_h * params.head_dim; 
            
            const validLen = pos - startPos + 1;
            const scores = new Float32Array(validLen);
            
            for (let i = 0; i < validLen; i++) {
                const p = startPos + i;
                const k_h = self.env.kv[l].k[p].subarray(kv_off, kv_off + params.head_dim);
                
                let dot = 0;
                for(let j=0; j<params.head_dim; j++) dot += q_h[j] * k_h[j];
                
                scores[i] = dot * scale;
            }

            // SOFT CAPPING (Attn) - Disabled for Gemma 3
            let cap_scores = scores;
            if (params.attn_soft_cap > 0) {
                cap_scores = self.softCap(scores, params.attn_soft_cap);
            }
            
            const probs = self.softmax(cap_scores);
            const out_h = out_attn.subarray(h_off, h_off + params.head_dim);
            
            for (let i = 0; i < validLen; i++) {
                const p = startPos + i;
                const val = probs[i];
                const v_h = self.env.kv[l].v[p].subarray(kv_off, kv_off + params.head_dim);
                for(let j=0; j<params.head_dim; j++) out_h[j] += val * v_h[j];
            }
        }
        
        let attn_proj_w = self.loadWeight(`${p}attn_out.weight`);
        return self.matVecMul(out_attn, attn_proj_w, params.n_embd);
    };


    
    self.computeFFN = function(x, l, params, prefix) {
        const p = `blk.${l}.`;
        
        let w_g = self.loadWeight(`${p}ffn_gate.weight`);
        let w_u = self.loadWeight(`${p}ffn_up.weight`);
        let w_d = self.loadWeight(`${p}ffn_down.weight`);
        
        if (!w_g || !w_u || !w_d) return new Float32Array(params.n_embd);

        const n_ff = w_g.length / params.n_embd;
        const gate = self.matVecMul(x, w_g, n_ff);
        const up = self.matVecMul(x, w_u, n_ff);
        
        // Activation
        let act;
        if (params.act_fn === 'gelu') {
            act = self.gelu(gate);
        } else {
            act = self.silu(gate);
        }

        for(let i=0; i<n_ff; i++) act[i] *= up[i];
        
        return self.matVecMul(act, w_d, params.n_embd);
    };


    
    self.forwardLayer = function(x, layerIdx, params, pos) {
        const l = layerIdx;
        const prefix = `blk.${l}.`;
        const unitOffset = 0.0;
        
        // Debug L0
        const debug = (l === 0 && pos === 0);
        
        // 1. PRE-ATTN NORM
        let attn_norm_w = self.loadWeight(`${prefix}attn_norm.weight`);
        let x_norm = self.rmsNorm(x, attn_norm_w, params.norm_eps, unitOffset);
        
        // 2. ATTENTION BLOCK
        let attn_out = self.computeAttention(x_norm, l, params, prefix, pos);
        
        // 3. POST-ATTN NORM (Gemma 3)
        // Gemma 3 applies normalization to the attention output BEFORE adding to residual?
        // gemma3.cpp:
        // cur = build_attn(...)
        // cur = build_norm(cur, model.layers[il].attn_post_norm, ...)
        // sa_out = ggml_add(ctx0, cur, inpL);  <-- Residual added AFTER post-norm
        let w_post_attn = self.loadWeight(`${prefix}attn_post_norm.weight`);
        if (w_post_attn) {
             attn_out = self.rmsNorm(attn_out, w_post_attn, params.norm_eps, unitOffset);
        }
        
        // RESIDUAL 1
        for(let i=0; i<x.length; i++) x[i] += attn_out[i];
        
        // 4. PRE-FFN NORM
        let ffn_norm_w = self.loadWeight(`${prefix}ffn_norm.weight`);
        let x_ffn_norm = self.rmsNorm(x, ffn_norm_w, params.norm_eps, unitOffset);
        
        // 5. FFN BLOCK
        let ffn_out = self.computeFFN(x_ffn_norm, l, params, prefix);
        
        // 6. POST-FFN NORM (Gemma 3)
        // gemma3.cpp:
        // cur = build_ffn(...)
        // cur = build_norm(cur, model.layers[il].ffn_post_norm, ...)
        // cur = ggml_add(ctx0, cur, sa_out); <-- Residual added AFTER post-norm
        let w_post_ffn = self.loadWeight(`${prefix}ffn_post_norm.weight`);
        if (w_post_ffn) {
            ffn_out = self.rmsNorm(ffn_out, w_post_ffn, params.norm_eps, unitOffset);
        }
        
        // RESIDUAL 2
        for(let i=0; i<x.length; i++) x[i] += ffn_out[i];
        
        if (debug) self.logStats(`L0 Output`, x);

        return x;
    };



    self.initSession = async function(buffer, meta) {
        self.env.buffer = buffer;
        self.env.metaKV = meta.kv;
        self.env.vocab = meta.vocab;
        
        // 1. Scan Tensors to find Data Offset
        const dataOffset = self.scanTensors(buffer, meta.endOffset, meta.tensorCount, meta.alignment);
        self.env.dataOffset = dataOffset;
        
        // 2. Infer Config
        self.env.stats = self.inferStats(meta);
        
        // 3. Map Weights
        if (self.autoMapWeights) self.autoMapWeights();

        // 4. Init WASM (B"H Turbo)
        if (self.initWasmKernel) {
             await self.initWasmKernel();
             if (self.resetWasmHeap) self.resetWasmHeap(); // CRITICAL: Reset heap for new session
        }
        
        // 5. Send Config to UI
        self.postMessage({ type: 'CONFIG', payload: self.env.stats });
        
        // 6. Send Tensor List to UI
        const tensorList = Array.from(self.env.tensorMap.values()).map(t => ({
            name: t.name,
            dims: t.dims,
            type: t.type,
            size: (t.dims.reduce((a,b)=>a*b,1) * self.getByteSize(t.type).blockSize) / self.getByteSize(t.type).blockElements
        }));
        self.postMessage({ type: 'TENSORS', payload: tensorList });

        self.env.isInitialized = true;
        self.env.pos = 0;
        self.env.history = [];
        self.env.kv = [];
        
        // Initialize the loader helper
        self.initLoader(buffer, meta);
    };

    self.runInference = async function(params, onToken, onDone) {
        if (!self.env.stats) throw new Error("Engine not ready");
        
        // params is now an object: { prompt, temp, top_p, penalty, max_tokens }
        const prompt = params.prompt;
        const config = {
            temp: params.temp || 0.8,
            top_p: params.top_p || 0.9,
            repeat_penalty: params.penalty || 1.1,
            max_tokens: params.max_tokens || 512
        };

        self.env.stop = false;
        self.env.hasLoggedWasmUsage = false; // Reset log flag
        self.logDB(`--- INFERENCE START ---`, 'accent');
        
        // Log Raw Prompt
        // self.logDB(`[PROMPT] Raw: ${JSON.stringify(prompt)}`, 'read');

        // 1. Tokenize
        let tokens = self.tokenize(prompt);
        
        // Gemma specific: Add BOS (2) if start of session
        if (self.env.pos === 0 && self.env.stats.arch.includes('gemma')) {
             if (tokens[0] !== 2) {
                 tokens.unshift(2);
                 self.logDB(`[PROMPT] Added BOS (2) at start`, 'warn');
             }
        }

        // Log Tokens
        self.logDB(`[PROMPT] IDs: [${tokens.join(', ')}]`, 'info');
        const tokenStrs = tokens.map(id => {
            const s = self.env.vocab[id];
            return s ? s.replace('\u2581', '_').replace(/\n/g, '\\n') : 'UNK';
        });
        self.logDB(`[PROMPT] Toks: ${tokenStrs.join(' ')}`, 'info');

        self.logDB(`Processing ${tokens.length} tokens...`, 'info');
        
        // 2. Prompt Processing
        let nextToken = null;
        for (let i = 0; i < tokens.length; i++) {
            if (self.env.stop) break;
            // Only the last token needs generation phase sampling logic
            const phase = (i === tokens.length - 1) ? 'GEN' : 'PROMPT';
            
            // B"H - Async processing allows event loop to check for STOP
            nextToken = await self.processToken(tokens[i], phase, config);
        }
        
        // 3. Generation Loop
        let generated = 0;
        
        if (nextToken !== null) { 
             while (!self.env.stop && generated < config.max_tokens) {
                if (nextToken === 1 || nextToken === 106 || nextToken === 2) { 
                    self.logDB("EOS Reached", 'info');
                    break;
                }
                
                const text = self.getWord(nextToken);
                onToken(text);
                
                generated++;
                
                // B"H - Yield to allow UI updates and Stop signals
                await new Promise(r => setTimeout(r, 0));
                
                nextToken = await self.processToken(nextToken, 'GEN', config);
            }
        }
        
        onDone();
    };

    self.getWord = function(id) {
        let w = self.env.vocab[id];
        if (!w) return '';
        if (typeof w !== 'string') return ''; 
        return w.replace('\u2581', ' ').replace('<0x0A>', '\n');
    };

    self.processToken = async function(id, phase, config) {
        const stats = self.env.stats;
        const currentPos = self.env.pos;
        
        // B"H - Performance Tuning
        const TIME_BUDGET_MS = 100;
        let startTime = performance.now();

        // 1. Embedding
        let x = self.getEmbeddingRow(id, stats.n_embd);
        if (!x) throw new Error("Embedding Missing for ID: " + id);

        // Scale (Gemma)
        if (stats.useEmbScale) {
            const embScale = Math.sqrt(stats.n_embd);
            for(let i=0; i<x.length; i++) x[i] *= embScale;
        }

        // 2. Layers
        for (let l = 0; l < stats.n_layer; l++) {
            if (self.env.stop) return -1;
            
            x = self.forwardLayer(x, l, stats, currentPos);
            
            if (performance.now() - startTime > TIME_BUDGET_MS) {
                 await new Promise(r => setTimeout(r, 0));
                 startTime = performance.now();
            }
        }

        // 3. Final Norm
        let w_norm = self.loadWeight('output_norm.weight');
        if (w_norm) x = self.rmsNorm(x, w_norm, stats.norm_eps, 0.0);

        // 4. Logits
        if (phase === 'GEN') {
            const w_out = self.loadWeight('output.weight', false) || self.loadWeight('token_embd.weight', false);
            const logits = self.matVecMul(x, w_out, self.env.vocab.length);

            // FINAL SOFT CAPPING (Gemma 3)
            if (stats.final_soft_cap > 0) {
                const cap = stats.final_soft_cap;
                const invCap = 1.0 / cap;
                for(let i=0; i<logits.length; i++) {
                    logits[i] = cap * Math.tanh(logits[i] * invCap);
                }
            }
            
            // SAMPLING
            const nextId = self.sampleToken(logits, self.env.history, config);
            
            self.env.pos++;
            self.env.history.push(nextId);
            return nextId;
        } else {
            // PROMPT phase
            self.env.pos++;
            self.env.history.push(id);
            return -1;
        }
    };
    
    self.sampleToken = function(logits, history, params) {
        const temp = params.temp; // 0.8 default
        const top_p = params.top_p; // 0.9 default
        const penalty = params.repeat_penalty; // 1.1 default
        const penalty_n = 64; // Lookback window
        
        // 0. Greedy Bypass if temp is very low
        if (temp < 0.01) {
             let maxVal = -Infinity;
             let maxId = 0;
             for(let i=0; i<logits.length; i++) {
                 if (logits[i] > maxVal) { maxVal = logits[i]; maxId = i; }
             }
             return maxId;
        }

        // 1. Repetition Penalty
        // Apply penalty to logits of recently seen tokens
        const start = Math.max(0, history.length - penalty_n);
        const context = history.slice(start);
        const seen = new Set(context);
        
        for (const id of seen) {
            // Llama.cpp style penalty: if logit > 0, divide. if logit < 0, multiply.
            if (logits[id] > 0) logits[id] /= penalty;
            else logits[id] *= penalty;
        }

        // 2. Temperature scaling
        // Find max for numerical stability
        let maxLogit = -Infinity;
        for (let i = 0; i < logits.length; i++) {
            logits[i] /= temp;
            if (logits[i] > maxLogit) maxLogit = logits[i];
        }
        
        // 3. Softmax
        const probs = new Float32Array(logits.length);
        let sum = 0;
        for (let i = 0; i < logits.length; i++) {
            const p = Math.exp(logits[i] - maxLogit);
            probs[i] = p;
            sum += p;
        }
        if (sum === 0) sum = 1; // Prevent division by zero if all probs are zero

        // 4. Top-P (Nucleus) Sampling
        // Create candidates array [id, p]
        let candidates = [];
        const threshold = 0.0001 / self.env.vocab.length; 
        
        for(let i=0; i<probs.length; i++) {
            const norm_p = probs[i] / sum;
            if (norm_p > threshold) {
                 candidates.push({ id: i, p: norm_p });
            }
        }
        
        // Sort descending by probability
        candidates.sort((a, b) => b.p - a.p);
        
        // B"H - ROBUSTNESS: Handle empty candidates from faulty models
        if (candidates.length === 0) {
            self.logDB('[SAMPLER] CRITICAL: All candidates filtered. Logits may be NaN or all -Infinity. Taking top logit as fallback.', 'error');
            let maxVal = -Infinity;
            let maxId = 0; // Default to padding token
            for(let i=0; i<logits.length; i++) {
                if (isFinite(logits[i]) && logits[i] > maxVal) { maxVal = logits[i]; maxId = i; }
            }
            return maxId;
        }

        let cumSum = 0;
        let cutoff = candidates.length - 1;
        
        for (let i = 0; i < candidates.length; i++) {
            cumSum += candidates[i].p;
            if (cumSum >= top_p) {
                cutoff = i;
                break;
            }
        }
        
        // Log Top 5 for debug (only first few gens to save logs)
        if (self.env.pos % 50 === 0 && candidates.length > 0) {
             let msg = `[GEN ${self.env.pos}] Top 5:\n`;
             for(let k=0; k<Math.min(5, candidates.length); k++) {
                 const c = candidates[k];
                 const word = (self.env.vocab[c.id]||"").replace('\n','\\n').replace('\u2581','_');
                 msg += `  ${k+1}. [${c.id}] "${word}" (${(c.p*100).toFixed(1)}%)\n`;
             }
             self.logDB(msg, 'calc');
        }

        // 5. Random Choice within Top-P
        // We re-normalize within the cutoff subset for correct distribution
        // Or simpler: generate random number up to cumSum of cutoff
        const r = Math.random() * cumSum;
        let acc = 0;
        for (let i = 0; i <= cutoff; i++) {
            acc += candidates[i].p;
            if (acc >= r) return candidates[i].id;
        }
        
        return candidates[0].id; // Fallback
    };


    
    self.WasmConst = {
        MAGIC: [0x00, 0x61, 0x73, 0x6d],
        VERSION: [0x01, 0x00, 0x00, 0x00],
        
        // Sections
        SECTION_TYPE: 1,
        SECTION_IMPORT: 2,
        SECTION_FUNCTION: 3,
        SECTION_MEMORY: 5,
        SECTION_EXPORT: 7,
        SECTION_CODE: 10,

        // Types
        I32: 0x7f,
        F32: 0x7d,
        V128: 0x7b,
        VOID: 0x40,
        FUNC: 0x60,

        // Control Flow
        BLOCK: 0x02,
        LOOP: 0x03,
        BR: 0x0c,
        BR_IF: 0x0d,
        RETURN: 0x0f,
        CALL: 0x10,
        END: 0x0b,

        // Variables
        LOCAL_GET: 0x20,
        LOCAL_SET: 0x21,
        LOCAL_TEE: 0x22,

        // I32 Ops
        I32_CONST: 0x41,
        I32_ADD: 0x6a,
        I32_SUB: 0x6b,
        I32_MUL: 0x6c,
        I32_SHL: 0x74,
        I32_LT_S: 0x48,
        I32_LE_S: 0x4c,
        I32_GE_S: 0x4e,

        // F32 Ops
        F32_CONST: 0x43,
        F32_LOAD: 0x2a,
        F32_STORE: 0x38,
        F32_ADD: 0x92,
        // f32.mul is 0x94
        F32_MUL: 0x94,

        // SIMD Ops (LEB128 Encoded IDs)
        SIMD_PREFIX: 0xfd,
        
        V128_LOAD: [0x00], 
        V128_STORE: [0x0b], 
        V128_CONST: [0x0c],
        V128_SHUFFLE: [0x0d],
        
        // f32x4.add -> ID 228 -> 0xE4 0x01
        F32x4_ADD: [0xe4, 0x01],
        
        // f32x4.mul -> ID 230 -> 0xE6 0x01
        F32x4_MUL: [0xe6, 0x01],
        
        // f32x4.extract_lane -> ID 33 -> 0x21
        F32x4_EXTRACT_LANE: [0x21],
    };

    self.WasmEncoder = {
        /**
         * B"H
         * Encodes an integer as a LEB128 sequence.
         */
        toLEB128: (num) => {
            const bytes = [];
            let n = num;
            while (true) {
                let byte = n & 0x7f;
                n >>>= 7;
                if (n === 0) { bytes.push(byte); break; }
                bytes.push(byte | 0x80);
            }
            return bytes;
        },

        // Helper to encode SIMD ops consistently
        simd: (bytes) => {
            return [0xfd, ...bytes];
        },
        
        // Encode locals header: [NumGroups, Count, Type]
        encodeLocal: (count, type) => {
            return [0x01, ...self.WasmEncoder.toLEB128(count), type];
        },
        
        createSection: (id, payload) => {
            return [id, ...self.WasmEncoder.toLEB128(payload.length), ...payload];
        }
    };



    self.WasmKernels = {
        /**
         * Function 0: dot
         * (ptrA: i32, ptrB: i32, count: i32) -> f32
         */
        generateDot: () => {
            const C = self.WasmConst;
            const E = self.WasmEncoder;

            // Locals: 
            // 0: ptrA, 1: ptrB, 2: count
            // 3: acc (v128)
            // 4: scalar_acc (f32)
            
            const locals = [
                0x02, // 2 Groups
                0x01, C.V128, // 1 x v128 (idx 3)
                0x01, C.F32   // 1 x f32  (idx 4)
            ];

            const code = [
                // 1. Init Accumulator (v128) to 0
                ...E.simd(C.V128_CONST), ...new Array(16).fill(0),
                C.LOCAL_SET, 3,
                
                // Init Scalar Accumulator (f32) to 0.0
                C.F32_CONST, 0x00, 0x00, 0x00, 0x00,
                C.LOCAL_SET, 4,

                // 2. Hybrid Logic: Block 0 -> Block 1 (Turbo) -> Block 2 (Safe)
                C.BLOCK, C.VOID, // Block 0
                    C.BLOCK, C.VOID, // Block 1
                        C.LOOP, C.VOID, // Turbo Loop
                            // Guard: if count < 8 (2x unroll), break to Safe Block
                            // B"H - Simplified to 2x unroll (8 floats) for safety
                            C.LOCAL_GET, 2,
                            C.I32_CONST, 8,
                            C.I32_LT_S,
                            C.BR_IF, 1, // Break to Block 0 (Outer)

                            // Body 2x Unroll
                            C.LOCAL_GET, 0, ...E.simd(C.V128_LOAD), 0x00, 0x00, 
                            C.LOCAL_GET, 1, ...E.simd(C.V128_LOAD), 0x00, 0x00, 
                            ...E.simd(C.F32x4_MUL),
                            C.LOCAL_GET, 3, ...E.simd(C.F32x4_ADD), C.LOCAL_SET, 3,

                            C.LOCAL_GET, 0, ...E.simd(C.V128_LOAD), 0x00, 16,
                            C.LOCAL_GET, 1, ...E.simd(C.V128_LOAD), 0x00, 16,
                            ...E.simd(C.F32x4_MUL),
                            C.LOCAL_GET, 3, ...E.simd(C.F32x4_ADD), C.LOCAL_SET, 3,

                            // Pointers += 32
                            C.LOCAL_GET, 0, C.I32_CONST, 32, C.I32_ADD, C.LOCAL_SET, 0,
                            C.LOCAL_GET, 1, C.I32_CONST, 32, C.I32_ADD, C.LOCAL_SET, 1,
                            
                            // Count -= 8
                            C.LOCAL_GET, 2, C.I32_CONST, 8, C.I32_SUB, C.LOCAL_SET, 2,

                            C.BR, 0, // Repeat Turbo
                        C.END,
                    C.END, // End Turbo Block

                    // Safe Loop (1x) - Handles remainder of 8 (groups of 4)
                    C.LOOP, C.VOID,
                        C.LOCAL_GET, 2,
                        C.I32_CONST, 4,
                        C.I32_LT_S,
                        C.BR_IF, 1, // Break to Reduction

                        C.LOCAL_GET, 0, ...E.simd(C.V128_LOAD), 0x00, 0x00,
                        C.LOCAL_GET, 1, ...E.simd(C.V128_LOAD), 0x00, 0x00,
                        ...E.simd(C.F32x4_MUL),
                        C.LOCAL_GET, 3, ...E.simd(C.F32x4_ADD), C.LOCAL_SET, 3,

                        C.LOCAL_GET, 0, C.I32_CONST, 16, C.I32_ADD, C.LOCAL_SET, 0,
                        C.LOCAL_GET, 1, C.I32_CONST, 16, C.I32_ADD, C.LOCAL_SET, 1,
                        C.LOCAL_GET, 2, C.I32_CONST, 4, C.I32_SUB, C.LOCAL_SET, 2,
                        C.BR, 0,
                    C.END,
                C.END, // End Block 0

                // 3. Reduction (Address 0 store approach)
                // Store v128 to address 0
                C.I32_CONST, 0, // Address
                C.LOCAL_GET, 3, // acc
                ...E.simd(C.V128_STORE), 0x00, 0x00, 

                // Load 4 floats and sum
                C.I32_CONST, 0, C.F32_LOAD, 0x00, 0x00,
                C.I32_CONST, 0, C.F32_LOAD, 0x00, 0x04,
                C.F32_ADD,
                C.I32_CONST, 0, C.F32_LOAD, 0x00, 0x08,
                C.F32_ADD,
                C.I32_CONST, 0, C.F32_LOAD, 0x00, 0x0C,
                C.F32_ADD,

                // Add to scalar acc
                C.LOCAL_GET, 4,
                C.F32_ADD,
                C.LOCAL_SET, 4,

                // 4. Scalar Tail (Handle 0-3 remaining floats)
                C.BLOCK, C.VOID,
                    C.LOOP, C.VOID,
                        C.LOCAL_GET, 2,
                        C.I32_CONST, 0,
                        C.I32_LE_S, 
                        C.BR_IF, 1, 
                        
                        C.LOCAL_GET, 0, C.F32_LOAD, 0x00, 0x00,
                        C.LOCAL_GET, 1, C.F32_LOAD, 0x00, 0x00,
                        C.F32_MUL,
                        C.LOCAL_GET, 4,
                        C.F32_ADD,
                        C.LOCAL_SET, 4,

                        C.LOCAL_GET, 0, C.I32_CONST, 4, C.I32_ADD, C.LOCAL_SET, 0,
                        C.LOCAL_GET, 1, C.I32_CONST, 4, C.I32_ADD, C.LOCAL_SET, 1,
                        C.LOCAL_GET, 2, C.I32_CONST, 1, C.I32_SUB, C.LOCAL_SET, 2,

                        C.BR, 0,
                    C.END,
                C.END,

                C.LOCAL_GET, 4,
                C.END
            ];

            return { locals, code };
        },

        /**
         * Function 1: mv_mul
         * (ptrMat, ptrVec, ptrOut, rows, cols) -> void
         */
        generateMvMul: () => {
            const C = self.WasmConst;
            const E = self.WasmEncoder;

            // Locals: [1 x i32] (Index 5: i)
            const locals = E.encodeLocal(1, C.I32);

            const code = [
                // i = 0
                C.I32_CONST, 0, C.LOCAL_SET, 5,

                C.BLOCK, C.VOID,
                    C.LOOP, C.VOID,
                        // if i >= rows, break
                        C.LOCAL_GET, 5,
                        C.LOCAL_GET, 3,
                        C.I32_GE_S,
                        C.BR_IF, 1,

                        // Prepare Store Address
                        C.LOCAL_GET, 2, // ptrOut

                        // Call dot(ptrMat, ptrVec, cols)
                        C.LOCAL_GET, 0, // ptrMat
                        C.LOCAL_GET, 1, // ptrVec
                        C.LOCAL_GET, 4, // cols
                        C.CALL, 0,

                        // Store f32 (0x38)
                        C.F32_STORE, 0x00, 0x00, 

                        // Update ptrMat += cols * 4
                        C.LOCAL_GET, 0,
                        C.LOCAL_GET, 4, // cols
                        C.I32_CONST, 2,
                        C.I32_SHL,
                        C.I32_ADD,
                        C.LOCAL_SET, 0,

                        // Update ptrOut += 4
                        C.LOCAL_GET, 2,
                        C.I32_CONST, 4,
                        C.I32_ADD,
                        C.LOCAL_SET, 2,

                        // i++
                        C.LOCAL_GET, 5,
                        C.I32_CONST, 1,
                        C.I32_ADD,
                        C.LOCAL_SET, 5,

                        C.BR, 0,
                    C.END,
                C.END,
                C.END
            ];

            return { locals, code };
        }
    };


    
    self.WasmAssembler = class WasmAssembler {
        constructor() {
            if (!self.WasmConst || !self.WasmEncoder || !self.WasmKernels) {
                throw new Error("Asm dependencies missing.");
            }
        }

        buildBinary() {
            const C = self.WasmConst;
            const E = self.WasmEncoder;
            const K = self.WasmKernels;
            
            // 1. Generate Kernel Logic
            const f0 = K.generateDot();
            const f1 = K.generateMvMul();
            
            const body0 = [...f0.locals, ...f0.code];
            const size0 = E.toLEB128(body0.length);
            const func0Entry = [...size0, ...body0];

            const body1 = [...f1.locals, ...f1.code];
            const size1 = E.toLEB128(body1.length);
            const func1Entry = [...size1, ...body1];
            
            // Section 1: Type
            const typePayload = [
                0x02, // count
                // Type 0: dot(ptrA, ptrB, count) -> f32
                0x60, 0x03, C.I32, C.I32, C.I32, 0x01, C.F32, 
                // Type 1: mv_mul(ptrMat, ptrVec, ptrOut, rows, cols) -> void
                0x60, 0x05, C.I32, C.I32, C.I32, C.I32, C.I32, 0x00 
            ];
            const secType = E.createSection(C.SECTION_TYPE, typePayload);

            // Section 2: Import (Memory)
            // Must specify at least 32768 pages (2GB) here or during instantiation to match expectations
            // B"H - Updated to 0x03 (Shared + Max) to match JS SharedArrayBuffer
            const minPages = E.toLEB128(32768);   
            const maxPages = E.toLEB128(32768); 
            
            const importPayload = [
                0x01, // 1 Import
                0x03, ...[0x65, 0x6e, 0x76], // "env"
                0x06, ...[0x6d, 0x65, 0x6d, 0x6f, 0x72, 0x79], // "memory"
                0x02, 0x03, ...minPages, ...maxPages // 0x02=Mem, 0x03=Shared|HasMax
            ];
            const secImport = E.createSection(C.SECTION_IMPORT, importPayload);

            // Section 3: Function
            const funcPayload = [
                0x02, // 2 Funcs
                0x00, // Type index 0
                0x01  // Type index 1
            ];
            const secFunc = E.createSection(C.SECTION_FUNCTION, funcPayload);

            // Section 7: Export
            const exportPayload = [
                0x02, // 2 Exports
                0x03, 0x64, 0x6f, 0x74, 0x00, 0x00, // "dot" -> index 0
                0x06, 0x6d, 0x76, 0x5f, 0x6d, 0x75, 0x6c, 0x00, 0x01 // "mv_mul" -> index 1
            ];
            const secExport = E.createSection(C.SECTION_EXPORT, exportPayload);

            // Section 10: Code
            const codePayload = [
                0x02, // 2 Func Bodies
                ...func0Entry,
                ...func1Entry 
            ];
            const secCode = E.createSection(C.SECTION_CODE, codePayload);

            const buffer = new Uint8Array([
                ...C.MAGIC, ...C.VERSION,
                ...secType,
                ...secImport,
                ...secFunc,
                ...secExport,
                ...secCode
            ]);

            return buffer;
        }
    };


    
    // Constants
    const SCRATCH_SIZE = 32 * 1024 * 1024; // 32MB Scratch
    const PAGE_SIZE = 65536;

    self.wasmCtx = {
        instance: null,
        memory: null,
        heapF32: null,
        
        scratchPtr: 0,
        scratchLimit: SCRATCH_SIZE, 
        
        // Weights start after the scratch area
        permanentPtr: SCRATCH_SIZE, 
        permanentBase: SCRATCH_SIZE,
        shadowCache: new Map() // Strong Map to keep weights alive
    };

    self.initWasmKernel = async function() {
        if (self.wasmCtx.instance) return;

        try {
            self.logDB("Compiling JIT Wasm SIMD Kernel (Awtsmoos Hybrid)...", "accent");

            if (!self.WasmAssembler) throw new Error("WasmAssembler not loaded");

            const assembler = new self.WasmAssembler();
            const binary = assembler.buildBinary();

            // B"H - Reveal the Binary Soul (FULL HEX DUMP)
            const hexPart = self.toHex(binary); 
            self.logDB(`[WASM SOUL] Size: ${binary.length} bytes\n${hexPart}`, 'info');

            if (!WebAssembly.validate(binary)) throw new Error("Binary Validation Failed");

            // B"H - PHYSICS FIX: 2GB MEMORY
            // Model: 270M * 4 bytes = 1.08 GB.
            // We allocate 2GB (32768 pages) upfront.
            const initialPages = 32768; 
            const maxPages = 32768; 
            
            const memory = new WebAssembly.Memory({ 
                initial: initialPages, 
                maximum: maxPages,
                shared: true
            }); 
            
            self.wasmCtx.memory = memory;
            self.wasmCtx.heapF32 = new Float32Array(memory.buffer);

            const module = await WebAssembly.instantiate(binary, {
                env: { memory: memory }
            });

            self.wasmCtx.instance = module.instance;
            self.logDB(`Wasm Ruby Kernel Ready. Heap: ${initialPages * 64 / 1024} MB (2GB)`, "accent");
            self.env.useWasm = true;
        } catch (e) {
            self.logDB(`Wasm Init Failed: ${e.message}\n${e.stack}`, "error");
            self.env.useWasm = false;
        }
    };
    
    // B"H - Reset for new sessions
    self.resetWasmHeap = function() {
        if (!self.wasmCtx.instance) return;
        self.wasmCtx.permanentPtr = self.wasmCtx.permanentBase;
        self.wasmCtx.shadowCache = new Map(); 
        self.logDB("Wasm Permanent Heap Reset.", "warn");
    };

    self._wasmEnsureSpace = function(targetPtr, bytesNeeded) {
        const endAddress = targetPtr + bytesNeeded;
        if (endAddress > self.wasmCtx.memory.buffer.byteLength) {
             throw new Error(`Wasm Heap Overflow! Needed ${endAddress}, Limit ${self.wasmCtx.memory.buffer.byteLength}. Increase initialPages.`);
        }
    };

    self.wasmMatVecMul = function(x, w, n_out) {
        if (!self.wasmCtx.instance) return self.matVecMulJS(x, w, n_out); 

        // B"H - Strict Safety: Vectors must exist
        if (!w || w.length === 0 || !x || x.length === 0) {
             return new Float32Array(n_out);
        }

        const n_in = x.length;
        
        // B"H - Strict Safety: Alignment check for 128-bit SIMD (4 elements)
        // Also check if w is large enough
        if (n_in % 4 !== 0 || w.length < n_in * n_out) return self.matVecMulJS(x, w, n_out);

        // Reserve address 0-128 for Kernel Internal Scratch (Reduction)
        self.wasmCtx.scratchPtr = 128;
        
        // Safe Allocation Closure (Align to 16 bytes)
        const allocScratch = (count) => {
            const bytes = count * 4;
            const ptr = (self.wasmCtx.scratchPtr + 15) & ~15;
            if (ptr + bytes > self.wasmCtx.scratchLimit) {
                throw new Error(`Wasm Scratch Exhausted: Need ${ptr + bytes}, Limit ${self.wasmCtx.scratchLimit}`);
            }
            self.wasmCtx.scratchPtr = ptr + bytes;
            return ptr;
        };

        let ptr_w = 0;
        let ptr_x = 0;
        let ptr_y = 0;

        try {
            // Allocate Scratch Memory (Input vector, Output vector)
            ptr_x = allocScratch(n_in);
            ptr_y = allocScratch(n_out);
            
            // Allocate/Get Weight Matrix in Permanent Heap
            ptr_w = self.wasmCtx.shadowCache.get(w);
            if (ptr_w === undefined) {
                const bytes_w = w.length * 4;
                // Align weight start to 16 bytes
                const aligned_ptr = (self.wasmCtx.permanentPtr + 15) & ~15;
                
                self._wasmEnsureSpace(aligned_ptr, bytes_w);
                
                // Copy weights to Wasm Heap
                self.wasmCtx.heapF32.set(w, aligned_ptr / 4);
                ptr_w = aligned_ptr;
                
                self.wasmCtx.permanentPtr = aligned_ptr + bytes_w;
                self.wasmCtx.shadowCache.set(w, ptr_w);
            }

            // Copy Input Vector to Scratch
            self.wasmCtx.heapF32.set(x, ptr_x / 4); 
            
            // Execute Kernel (5 args: ptr_w, ptr_x, ptr_y, rows, cols)
            // Note: Scratch is implicitly address 0 in the kernel now.
            self.wasmCtx.instance.exports.mv_mul(ptr_w, ptr_x, ptr_y, n_out, n_in);

            // Read Result
            return self.wasmCtx.heapF32.slice(ptr_y / 4, (ptr_y / 4) + n_out);

        } catch (e) {
            // Log with detailed context
            if (!self.env.lastWasmError || self.env.lastWasmError !== e.message) {
                 self.logDB(`Wasm Trap (Recovered): ${e.message}. Falling back to JS. Params: ptr_w=${ptr_w}, ptr_x=${ptr_x}, ptr_y=${ptr_y}, rows=${n_out}, cols=${n_in}`, "warn");
                 self.env.lastWasmError = e.message;
            }
            return self.matVecMulJS(x, w, n_out);
        }
    };


    
    self.WasmPurifier = class WasmPurifier {
        /**
         * B"H
         * Prepares the surgical instruments for the model refinement.
         */
        constructor(buffer, meta, options) {
            this.oldBuffer = new Uint8Array(buffer);
            this.meta = meta;
            this.oldVocab = meta.vocab;
            this.oldScores = meta.scores || [];
            
            // Options: { keepStart, keepEnd, widthPct, vocabSize, regex, regexMode }
            this.keepStart = options.keepStart;
            this.keepEnd = options.keepEnd;
            this.widthPct = (options.widthPct || 100) / 100.0;
            this.targetVocab = options.vocabSize;
            this.regex = options.regex;
            this.regexMode = options.regexMode; // 'keep' or 'remove'
            
            self.logDB(`[PURIFY] Init: Layers Keep ${this.keepStart}/${this.keepEnd}, Width=${this.widthPct.toFixed(2)}, VocabTarget=${this.targetVocab}, RegexMode=${this.regexMode}`, 'info');
            
            this.specialIds = new Set();
            const kv = this.meta.kv;
            const specialKeys = ['tokenizer.ggml.bos_token_id', 'tokenizer.ggml.eos_token_id', 'tokenizer.ggml.unknown_token_id', 'tokenizer.ggml.padding_token_id', 'tokenizer.ggml.separator_token_id'];
            specialKeys.forEach(key => { if (kv[key] !== undefined) this.specialIds.add(kv[key]); });
            
            this.keptIndices = [];
            this.newVocabSize = 0;
            this.indexMap = new Int32Array(this.oldVocab.length).fill(-1);
            this.layerMap = new Map(); // Old Layer ID -> New Layer ID
        }

        async purify(onProgress) {
            let lastLogTime = performance.now();
            const LOG_INTERVAL_MS = 500;
            const yieldControl = async (msg, force = false) => {
                const now = performance.now();
                if (force || (now - lastLogTime > LOG_INTERVAL_MS)) {
                    onProgress(msg);
                    lastLogTime = now;
                    await new Promise(r => setTimeout(r, 0));
                }
            };

            await yieldControl("B\"H - Starting Purification...", true);
            this._selectVocab();
            await yieldControl(`Vocab Surgery: ${this.oldVocab.length} -> ${this.newVocabSize} tokens.`, true);

            let modelLayers = 0;
            const tensorNames = Array.from(self.env.tensorMap.keys());
            for (const name of tensorNames) {
                const match = name.match(/(?:blk|layers)\.(\d+)\./);
                if (match) modelLayers = Math.max(modelLayers, parseInt(match[1]) + 1);
            }
            
            this._planLayerSurgery(modelLayers);
            const keptLayerCount = this.layerMap.size;
            await yieldControl(`Layer Surgery: ${modelLayers} -> ${keptLayerCount} layers.`, true);

            const newKV = { ...this.meta.kv };
            newKV['tokenizer.ggml.tokens'] = this.keptIndices.map(i => this.oldVocab[i]);
            if (this.oldScores.length) newKV['tokenizer.ggml.scores'] = this.keptIndices.map(i => this.oldScores[i]);
            
            let blockCountKey = Object.keys(newKV).find(k => k.endsWith('.block_count'));
            if (blockCountKey) newKV[blockCountKey] = keptLayerCount;

            let originalFFNLen = 0, newFFN = 0;
            let ffnLenKey = Object.keys(newKV).find(k => k.endsWith('.feed_forward_length'));
            if (ffnLenKey && newKV[ffnLenKey]) {
                originalFFNLen = newKV[ffnLenKey];
                if (this.widthPct < 1.0) {
                    newFFN = Math.ceil((originalFFNLen * this.widthPct) / 256) * 256;
                    newKV[ffnLenKey] = newFFN;
                    await yieldControl(`Width Surgery: FFN ${originalFFNLen} -> ${newFFN}`, true);
                }
            }

            await yieldControl("Phase 4: Slicing Tensors...", true);
            const tensors = Array.from(self.env.tensorMap.values());
            const newTensorInfos = [];
            let currentDataOffset = 0;
            const alignment = this.meta.alignment || 32;
            const align = (offset) => (offset + alignment - 1) & ~(alignment - 1);
            
            for (const t of tensors) {
                let newName = t.name, dims = [...t.dims], data = null;
                const match = t.name.match(/(?:blk|layers)\.(\d+)\./);
                if (match) {
                    const oldL = parseInt(match[1]);
                    if (!this.layerMap.has(oldL)) continue;
                    newName = t.name.replace(`.${oldL}.`, `.${this.layerMap.get(oldL)}.`);
                }
                
                const oldRaw = self.getRawTensorView(t);
                if (!oldRaw) throw new Error("Source tensor corrupted: " + t.name);

                const isVocabTensor = t.dims.includes(this.oldVocab.length) && (newName.includes("token_embd") || newName.includes("output.weight") || newName.includes("lm_head"));
                const isGateUp = this.widthPct < 1.0 && originalFFNLen > 0 && (newName.includes("ffn_gate") || newName.includes("ffn_up") || newName.match(/w[13]\.weight/));
                const isDown = this.widthPct < 1.0 && originalFFNLen > 0 && (newName.includes("ffn_down") || newName.match(/w2\.weight/));

                if (isVocabTensor) data = this._sliceVocabTensor(t, dims, oldRaw);
                else if (isGateUp || isDown) data = this._sliceFFNTensor(t, dims, oldRaw, isGateUp, newFFN);
                else data = oldRaw;

                newTensorInfos.push({ name: newName, dims: dims, type: t.type, dataOffset: currentDataOffset, buffer: data });
                currentDataOffset = align(currentDataOffset + data.byteLength);
            }

            await yieldControl("Phase 5: Binding New Model Existence...", true);
            const finalGGUF = this.buildGGUF(newKV, newTensorInfos, alignment);
            const savings = (this.oldBuffer.byteLength - finalGGUF.byteLength) / (1024 * 1024);
            await yieldControl(`Surgery Successful. ${savings.toFixed(2)} MB removed.`, true);
            
            return finalGGUF;
        }

        _selectVocab() {
            const keepSet = new Set(this.specialIds);
            const knownSpecials = new Set(['<start_of_turn>', '<end_of_turn>', '<|eot_id|>']);

            // B"H - First pass: Absolutely preserve essential tokens
            for (let i = 0; i < this.oldVocab.length; i++) {
                const text = this.oldVocab[i];
                // Preserve all byte tokens and known special tokens
                if ((text.length === 6 && text.startsWith('<0x') && text.endsWith('>')) || knownSpecials.has(text)) {
                    keepSet.add(i);
                }
            }
            self.logDB(`[PURIFY] Preserved ${keepSet.size} essential control tokens.`, 'warn');

            const candidateIndices = [];
            let re = null;
            try { re = new RegExp(this.regex, 'u'); } catch (e) {
                self.logDB(`[PURIFY] Invalid Regex: ${e.message}`, 'error');
                re = /./; // Match everything as a fallback
            }

            for (let i = 0; i < this.oldVocab.length; i++) {
                // If it's already preserved, skip filtering
                if (keepSet.has(i)) continue;
                
                const text = this.oldVocab[i];
                const matches = re.test(text);
                if ((this.regexMode === 'keep' && matches) || (this.regexMode === 'remove' && !matches)) {
                    candidateIndices.push(i);
                }
            }

            // Sort filtered candidates by frequency score (higher is better)
            candidateIndices.sort((a, b) => (this.oldScores[b] || 0) - (this.oldScores[a] || 0));
            
            // Determine how many slots are left after accounting for essential tokens
            const remainingSlots = Math.max(0, this.targetVocab - keepSet.size);
            const finalCandidates = candidateIndices.slice(0, remainingSlots);
            finalCandidates.forEach(idx => keepSet.add(idx));

            this.keptIndices = [];
            for (let i = 0; i < this.oldVocab.length; i++) {
                if (keepSet.has(i)) {
                    this.indexMap[i] = this.keptIndices.length;
                    this.keptIndices.push(i);
                }
            }
            this.newVocabSize = this.keptIndices.length;
        }

        _planLayerSurgery(totalLayers) {
            this.layerMap.clear();
            const kStart = Math.min(this.keepStart, totalLayers);
            let kEnd = this.keepEnd;
            if (kStart + kEnd > totalLayers) kEnd = Math.max(0, totalLayers - kStart);
            
            for (let i = 0; i < kStart; i++) this.layerMap.set(i, i);
            const startEndBlock = totalLayers - kEnd;
            for (let i = 0; i < kEnd; i++) this.layerMap.set(startEndBlock + i, kStart + i);
        }

        _sliceVocabTensor(t, dims, oldRaw) {
            let vocabDimIdx = t.dims.findIndex(d => Math.abs(Number(d) - this.oldVocab.length) < 1024);
            if (vocabDimIdx === -1) return oldRaw; // Cannot determine vocab dimension
            
            dims[vocabDimIdx] = this.newVocabSize;
            const { blockElements, blockSize } = self.getByteSize(t.type);

            if (vocabDimIdx === 1) { // e.g., token_embd.weight [n_embd, n_vocab]
                const elementsPerRow = t.dims[0]; // n_embd
                const rowBytes = (elementsPerRow / blockElements) * blockSize;
                const data = new Uint8Array(this.newVocabSize * rowBytes);
                for (let i = 0; i < this.newVocabSize; i++) {
                    const srcStart = this.keptIndices[i] * rowBytes;
                    if (srcStart + rowBytes <= oldRaw.byteLength) {
                        data.set(oldRaw.subarray(srcStart, srcStart + rowBytes), i * rowBytes);
                    }
                }
                return data;
            } else if (vocabDimIdx === 0) { // e.g., output.weight [n_vocab, n_embd]
                const oldRows = t.dims[0];
                const newRows = this.newVocabSize;
                const elementsPerRow = t.dims[1]; // n_embd
                const rowBytes = (elementsPerRow / blockElements) * blockSize;
                const data = new Uint8Array(newRows * rowBytes);
                 for (let i = 0; i < newRows; i++) {
                    const srcStart = this.keptIndices[i] * rowBytes;
                    if (srcStart + rowBytes <= oldRaw.byteLength) {
                        data.set(oldRaw.subarray(srcStart, srcStart + rowBytes), i * rowBytes);
                    }
                }
                return data;
            }
            return oldRaw;
        }

        _sliceFFNTensor(t, dims, oldRaw, isGateUp, newFFN) {
             const { blockElements, blockSize } = self.getByteSize(t.type);
             if (isGateUp) { // Shape: [n_ff, n_embd], slice on n_ff (outer dim)
                 dims[0] = newFFN;
                 const newBytes = (newFFN / t.dims[0]) * oldRaw.byteLength;
                 return oldRaw.slice(0, newBytes);
             } else { // Shape: [n_embd, n_ff], slice on n_ff (inner dim)
                 dims[1] = newFFN;
                 const numRows = t.dims[0]; // n_embd
                 const oldRowBytes = (t.dims[1] / blockElements) * blockSize;
                 const newRowBytes = (newFFN / blockElements) * blockSize;
                 const data = new Uint8Array(numRows * newRowBytes);
                 for (let r = 0; r < numRows; r++) {
                     const srcStart = r * oldRowBytes;
                     data.set(oldRaw.subarray(srcStart, srcStart + newRowBytes), r * newRowBytes);
                 }
                 return data;
             }
        }

        buildGGUF(kv, tensorInfos, alignment = 32) {
            const encoder = new TextEncoder();
            const parts = [];
            const write = (data) => parts.push(data);
            const writeU32 = (val) => write(new Uint8Array(new Uint32Array([val]).buffer));
            const writeU64 = (val) => write(new Uint8Array(new BigUint64Array([BigInt(val)]).buffer));
            const writeStr = (str) => { const buf = encoder.encode(str); writeU64(buf.length); write(buf); };

            write(new Uint8Array([0x47, 0x47, 0x55, 0x46])); // GGUF
            writeU32(3); writeU64(tensorInfos.length); writeU64(Object.keys(kv).length);

            for (const [key, value] of Object.entries(kv)) {
                writeStr(key);
                if (typeof value === 'string') { writeU32(8); writeStr(value); }
                else if (typeof value === 'number') { if (Number.isInteger(value)) { writeU32(4); writeU32(value); } else { writeU32(6); write(new Uint8Array(new Float32Array([value]).buffer)); } }
                else if (Array.isArray(value)) {
                    writeU32(9);
                    if (value.length === 0 || typeof value[0] === 'string') { writeU32(8); writeU64(value.length); value.forEach(s => writeStr(s || "")); }
                    else if (typeof value[0] === 'number') { const isF = !Number.isInteger(value[0]); writeU32(isF ? 6 : 5); writeU64(value.length); write(new Uint8Array((isF ? new Float32Array(value) : new Int32Array(value)).buffer)); }
                }
                else if (typeof value === 'boolean') { writeU32(7); write(new Uint8Array([value ? 1 : 0])); }
            }
            
            for (const t of tensorInfos) { writeStr(t.name); writeU32(t.dims.length); t.dims.forEach(d => writeU64(d)); writeU32(t.type); writeU64(t.dataOffset); }

            let currentSize = parts.reduce((a, b) => a + b.byteLength, 0);
            let padSize = ((currentSize + alignment - 1) & ~(alignment - 1)) - currentSize;
            if (padSize > 0) write(new Uint8Array(padSize));

            for (const t of tensorInfos) { write(t.buffer); padSize = ((t.buffer.byteLength + alignment - 1) & ~(alignment - 1)) - t.buffer.byteLength; if (padSize > 0) write(new Uint8Array(padSize)); }

            const totalSize = parts.reduce((a, b) => a + b.byteLength, 0);
            const out = new Uint8Array(totalSize);
            let offset = 0;
            for (const p of parts) { out.set(p, offset); offset += p.byteLength; }
            return out.buffer;
        }
    };
